pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual_ratio = post / bin_capacity as f64;

    // Penalize creating tiny gaps (fragmentation) that are harder to fill later.
    // The "sweet spot" is either 0 (perfect fit) or large enough to accommodate future items.
    let fragmentation_penalty = if post > 0.0 && post < 20.0 {
        (20.0 - post).powi(2) * 2.5
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor leaving space for it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Dynamic threshold: As the stream progresses, become more aggressive in packing 
    // to avoid opening new bins late in the game.
    let progress_weight = 1.0 + (progress * 5.0);

    // Evaluate the cost of opening a new bin vs filling existing.
    // If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    let base_score = if bin_residual == bin_capacity {
        // New bin cost: increase as we near the end of the stream
        15.0 + (progress * 40.0) + (open_bins_count as f64 * 0.5)
    } else {
        // Existing bin cost: emphasize tight fits (low post_residual)
        (post * 0.8) + fragmentation_penalty + lookahead_penalty
    };

    // Coupling: If fitting_bins_count is low, we are constrained; lower the score 
    // to prioritize existing bins over opening new ones.
    let constraint_factor = if fitting_bins_count <= 1 { -5.0 } else { 0.0 };

    (base_score * progress_weight) + constraint_factor
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" waste (small remaining space).
    // If post_residual is very small (e.g., < 10), it's often better to leave a larger gap for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Coupling: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // 3. Global State Awareness: If we have many open bins, push toward consolidating (lower post_residual).
    // If we have very few bins, be more selective to avoid opening a new one later.
    let bin_pressure = (open_bins_count as f64) / (10.0 + progress * 50.0);
    score += bin_pressure * 15.0;

    // 4. New-Bin Thresholding: Discourage opening a new bin unless the current fit is catastrophic.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing fitting bins are all "poor" (high post_residual).
        // If fitting_bins_count is 0, we MUST open a new bin.
        if fitting_bins_count == 0 {
            score = -100.0;
        } else {
            // Otherwise, make the new bin score unattractive to force reuse.
            score = 60.0 + (mean_residual * 0.5);
        }
    } else {
        // Incentivize filling bins that are already partially full to keep global mean_residual low.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post_residual (Best Fit logic)
    let mut score = post;

    // Penalize creating "fragmented" bins (post_residual < 10) that are difficult to fill later
    // The penalty scales with progress; as the stream nears the end, we care less about fragmentation.
    if post_residual < 10 && post_residual > 0 {
        score += (10.0 - post) * (1.0 - progress).powf(0.5) * 5.0;
    }

    // Lookahead: If next item exists, penalize bins that cannot fit it, 
    // unless this is a very late stage in the stream.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post) * (1.0 - progress).powf(2.0) * 2.0;
    }

    // New Bin Penalty:
    // If the bin is brand new, add a penalty that decreases as we open more bins.
    // This discourages opening new bins early unless the fit is excellent.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - (open_bins_count as f64 / (1.0 + mean_residual)));
    }

    // Fitting Bins constraint:
    // If this is the only bin that can fit the item, reward it to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global density pressure:
    // If mean_residual is high, we are under-utilizing bins; penalize high post_residual more aggressively.
    score += (mean_residual / bin_capacity as f64) * post * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
