        score += 45.0;
    }

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Harmonic heuristic: favor fills that leave the residual as a multiple of common item granularities.
    // This reduces fragmentation by aligning potential future fits.
    score += (post_residual % 25) as f64 * 0.5;

    // If this is the last chance for the current item (fitting_bins_count == 1), 
    // we heavily penalize opening a new bin (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0;
    }

    // Progression scaling: As the stream nears completion, become more aggressive in packing
    // to avoid leaving trailing items in new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (100 - post_residual) as f64 * 0.2;
    }

    // Penalize high open_bins_count to encourage consolidation.
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (too small to fit typical future items)
    // If post_residual is small but > 0, it's often better to have it be 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead optimization: If the next item fits perfectly into this post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Balancing: If this is the last fitting bin, avoid opening a new one 
    // unless the current fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 4. Global Load Balancing: If we are early in the stream, favor filling existing bins.
    // As we approach the end, prioritize tight packing (minimizing post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 0.5);

    // 5. Mean residual sensitivity: If the current bin is significantly "emptier" 
    // than the average, prioritize it to keep other bins tighter.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 6. New Bin logic: Only open a new bin if the best existing fit is truly terrible.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin; only choose if existing options are highly inefficient.
        score = 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that cannot fit common small items (e.g., < 20).
    // If post_residual is in the "danger zone" (1..19), we strongly penalize it.
    if post_residual > 0 && post_residual < 20 {
        score += 50.0 + (20.0 - post_residual as f64) * 5.0;
    }

    // Harmonic/Modulo logic: Favor bins that leave a residual which is a multiple of 20,
    // as these are more likely to accommodate future items (10, 20, 25, 40, 50).
    let residual_mod = post_residual % 20;
    score += residual_mod as f64 * 0.5;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // we heavily reward this bin to minimize total bins.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Constraint: If this is the only bin that fits the current item, 
    // we must prioritize it to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // New bin logic: Penalize opening a new bin unless the current open bins 
    // result in extremely poor fragmentation (high mean_residual).
    if bin_residual == bin_capacity {
        score += 30.0 + (mean_residual * 0.5);
    }

    // Progression scaling: As we approach the end of the stream, 
    // be more aggressive in packing to minimize the tail of the bin list.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are too small to fit common items (dead space)
    // We create a non-linear "valley" penalty for post_residuals in the range [1, 9].
    let dead_space_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Factor in lookahead: prioritize bins that leave space for the next item
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // Interaction between progress and mean_residual: 
    // As the stream progresses, favor packing tighter (lower mean_residual)
    let tightness_pressure = (mean_residual - post) * progress * 2.0;

    // Favor bins that are already "good fits" (Best Fit logic)
    // but modulate by the number of fitting bins to avoid opening new bins prematurely
    let fit_rarity_bonus = if fitting_bins_count == 1 { -15.0 } else { 0.0 };

    // Base score is the residual itself, modified by non-linear penalties
    let mut score = post + dead_space_penalty + lookahead_penalty + tightness_pressure + fit_rarity_bonus;

    // If this is a new bin (bin_residual == bin_capacity), add a significant penalty
    // to discourage opening new bins unless the existing ones are truly poor fits.
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual). 
    // If we open a new bin, penalize based on current average efficiency.
    if bin_residual == bin_capacity {
        score = mean_residual * 0.85;
    }

    // 2. Lookahead Coupling: If next_item_size fits in the post_residual, 
    // highly prioritize this bin to prepare for a "perfect" pair.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
        // Reward configurations that leave exactly 0 space for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. Fragmentation Penalty: Penalize tiny residuals that cannot fit common items (10..20).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Scarcity Constraint: If this is the last fitting bin, prioritize it 
    // to avoid the overhead of opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression Weighting: As the stream nears completion, become more 
    // aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We penalize larger post_residuals to keep bins tight.
    let mut score = post_res;

    // Non-linear penalty for creating "dead space" (post_residual).
    // As the stream progresses, we become more aggressive about filling bins tightly.
    score += post_res.powf(1.5) * (1.0 + progress);

    // If next_item_size is known, penalize bin choices that prevent the next item from fitting.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Significant penalty for stranding a bin such that the next item cannot fit.
            score += (next_item_size as f64 - post_res) * 5.0;
        }
    }

    // Heuristic for opening a new bin:
    // If we are currently at the "new bin" candidate (bin_residual == bin_capacity),
    // we only return a low score if the current mean_residual is very high (meaning bins are loosely packed).
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early in the stream.
        // Opening a new bin is only attractive if existing bins are poorly utilized (mean_residual > 30).
        score = 100.0 + (mean_residual * 2.0) + (progress * 50.0);
    } else {
        // If this bin is the only one that can fit the item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Penalize bins that deviate significantly from the mean_residual to promote uniformity.
        score += (post_res - mean_residual).abs() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize values below the expected next item size (approximated by 100 - mean_residual).
    let expected_next = 100.0 - mean_residual;
    if post_res < expected_next {
        score += (expected_next - post_res).powf(1.5);
    }

    // Dynamic pressure: As the stream progresses, we become more conservative about opening new bins.
    // If it's a new bin (bin_residual == bin_capacity), increase cost based on stream progress.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 + progress.powi(2));
    }

    // Lookahead coupling: If a next item exists, penalize residuals that are too small to fit it.
    if next_item_size > 0 {
        if post_res > 0.0 && post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res) * 2.0;
        }
    }

    // Reward bins that have residuals close to the global mean, promoting uniform bin utilization.
    let dev_from_mean = (post_res - mean_residual).abs();
    score += dev_from_mean * 0.5;

    // If this is the last fitting bin, slightly lower the score to prioritize filling it 
    // rather than opening a new one, unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

