        score += 200.0;
    }

    // 2. Best-Fit logic: prioritize bins that leave the smallest post_residual
    // This is already partially captured by returning post_residual, 
    // but we refine it by penalizing bins that leave "useless" space (too small for common items)
    if post_residual < 10 {
        // Excellent fit: reward it
        score -= 50.0;
    }

    // 3. Lookahead Matching (Aggressive 2-step)
    // If we have a next item, try to leave exactly enough room for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // If we can fit the next item perfectly, reduce the score
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.5;
        } else {
            // If the post_residual is too small for the next item, penalize it 
            // because it forces a new bin later.
            score += 30.0;
        }
    }

    // 4. Mean Residual Balancing
    // If the post_residual is significantly higher than the current mean, 
    // we are making the bin "worse" than average.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Progression scaling
    // As we approach the end of the stream, prioritize closing bins (lower residuals)
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that is too small for common item sizes
    // If post_residual is small but not zero, it's often a bad fit
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // Lookahead logic: if next item is large, avoid leaving small residuals
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize blocking the next item from this bin
            score += 15.0 * (1.0 - progress);
        } else {
            // Reward keeping space for the next item
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Global state: if we have many bins open, try to consolidate
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // Dynamic threshold: if this is the last chance for an item, prioritize fitting it
    // fitting_bins_count == 1 means we are forced to pick this or open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New bin logic: penalize opening a new bin unless it's the only way to avoid a very poor fit
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 45.0;

        // If we are near the end of the stream, discourage opening new bins
        score += progress * 30.0;

        // If current mean residual is high, we have enough space elsewhere
        score += mean_residual * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, aiming for Best Fit (minimized post_residual)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        // Penalty scales with current open bin density and normalized progress.
        // We add a large constant to make it less attractive than existing bins.
        score += 80.0 + (progress * 40.0) + (open_bins_count as f64 * 2.0);
    } else {
        // Reward bins that leave residual space close to the mean_residual of other bins,
        // promoting uniform packing density across the bin set.
        let density_alignment = (post_residual as f64 - mean_residual).abs();
        score += density_alignment * 0.5;

        // Lookahead heuristic: If the next item is large, prioritize bins that can fit it.
        // If the current post_residual is too small for the next item, penalize it slightly
        // to keep larger gaps available for future items.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }

        // If this is the last fitting bin, reward it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Non-linear coupling: penalize very small residuals (dead space) that are too small 
    // to likely fit future items, but only if we are in the later stages of the stream.
    if post_residual < 10 && post_residual > 0 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We define "dead" as < 10 (since minimum item size is likely small, but we prioritize tight fills).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Harmonic logic: Favor fills that leave residuals which are multiples of common item sizes.
    // If the post_residual is a multiple of 20, it is highly flexible for future items.
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead logic: If we know the next item, prioritize bins that create a post_residual
    // that can accommodate the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
