    }

    // Threshold logic: If this is the only bin that fits the item, accept it to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Global state awareness: Encourage filling existing bins rather than creating new ones
    // as the stream progresses.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many open bins already.
        score += (open_bins_count as f64) * 5.0;

        // Normalize new bin score based on progress to prevent early-stream bloat.
        score += 20.0 * (step_index as f64 / total_items as f64);
    }

    // Mean residual balance: Avoid bins that deviate significantly from the average fullness.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

