pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the range [1, 9], it is highly likely to become
    // unusable "fragmentation" since the minimum item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Coupling: If next_item_size is known, penalize placements that leave too little
    // room for the next item, effectively acting as a Best-Fit-Decreasing approximation.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening a new bin if an existing one can accommodate the item.
    // If this is a new bin (bin_residual == bin_capacity), add a penalty based on how many
    // open bins are available to handle the current item.
    if bin_residual == bin_capacity {
        score += 30.0 + (fitting_bins_count as f64 * 15.0);
    }

    // 4. Global Efficiency: If the current bin's residual after placement is significantly 
    // lower than the mean residual, it is a high-density bin. Reward this to encourage filling 
    // bins to capacity.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become increasingly aggressive
    // about using existing bins (penalize opening new ones) to avoid stranded items.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating a new bin:
    // If this is the empty bin (residual == capacity), penalize it based on how many
    // existing bins could have taken the item.
    if bin_residual == bin_capacity {
        score += 45.0 + (fitting_bins_count as f64 * 5.0);
    }

    // 2. Lookahead matching:
    // If the post_residual is close to the next_item_size, we favor this bin (Best Fit behavior).
    // If post_residual is slightly smaller than next_item_size, it's a "bad" fit (fragmentation).
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 {
            // Perfect match reward
            score -= (100.0 - diff as f64) * 0.4;
        } else {
            // Penalty for stranding the next item
            score += 20.0;
        }
    }

    // 3. Efficiency alignment:
    // Penalize bins that deviate significantly from the mean residual of the set.
    // This keeps bin usage uniform and avoids creating "outlier" bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 4. Density pressure:
    // As the stream progresses, become more aggressive in packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 5. Critical Thresholding:
    // If this is the only bin that fits, heavily favor it to prevent unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits that leave little wasted space.
    // We penalize large post_residuals exponentially to favor "perfect" packing.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global Efficiency: If many bins are open, we are currently fragmented. 
    // Penalize opening new bins (bin_residual == bin_capacity) increasingly as the stream progresses.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 10.0 * (1.0 + progress);
        // If we are forced to open a new bin, penalize it less if we have very few fitting options.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // 4. Residual Balancing: Penalize bins that deviate significantly from the mean residual of open bins.
    // This encourages uniformity in bin usage (Best-Fit-like behavior).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Urgency: If this is the only bin that can fit the current item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Near-Fullness Bonus: Reward reaching a state where the bin is almost full (less than 10 units left).
    if post_residual < 10 {
        score -= (10 - post_residual) as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalty for opening a new bin: if bin_residual == capacity, we are evaluating a new bin.
    // We add a dynamic threshold based on progress to discourage opening new bins early in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // As the stream progresses, the cost to open a new bin decreases (1.0 -> 0.0)
        // to account for the need to clear remaining items.
        (1.0 - progress) * 45.0 + 5.0
    } else {
        0.0
    };

    // Best-Fit Decreasing (BFD) logic: Minimize post_residual.
    // We couple this with the lookahead (next_item_size) to avoid leaving gaps that 
    // are too small for the next item.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        // If the post_residual is too small for the next item, penalize proportionally
        // to how much space is wasted relative to the total capacity.
        (next_item_size - post_residual) as f64 * 0.8
    } else {
        0.0
    };

    // Reward bins that align with the mean_residual of the system to keep bins balanced.
    // This helps avoid creating a mix of very full and very empty bins.
    let balance_score = (post - mean_residual).abs() * 0.2;

    // Critical constraint: If this is the only bin that fits the item (fitting_bins_count == 1),
    // we should prioritize using it unless the new_bin_penalty is very low.
    let scarcity_multiplier = if fitting_bins_count == 1 && !is_new_bin {
        0.1
    } else {
        1.0
    };

    (post + new_bin_penalty + lookahead_penalty + balance_score) * scarcity_multiplier
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We prioritize bins that result in a residual that is a multiple of common item sizes or near zero.
    if post_residual > 0 {
        let remainder = post_residual % 10;
        score += (remainder as f64) * 1.5;
    }

    // Heuristic: If this is the only bin that fits the current item, prioritize it heavily
    // unless the residual is extremely inefficient (e.g., leaving 1-9 units).
    if fitting_bins_count == 1 && post_residual > 9 {
        score -= 50.0;
    }

    // Lookahead logic: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Favor filling bins that are already "half-empty" (mean_residual logic)
    // to keep the distribution of open bins uniform.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Threshold logic: discourage opening a new bin (bin_residual == bin_capacity)
    // unless the item is very large or the current open bins are all near-full.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && item_size < 70 {
            score += 60.0;
        } else {
            score += 20.0;
        }
    }

    // Progression scaling: As we reach the end of the stream, prioritize closing bins
    // by rewarding placements into bins that leave very little space.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 10 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to fill bins tightly, but heavily penalize 
    // "unusable" gaps (1..10) which are too small for any future item.
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (gaps smaller than the minimum possible item size).
    // If post_residual is in (0, 10), we treat it as a significant waste.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // Heuristic: If this is the only bin that can fit the item, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Pressure factor: Penalize opening a new bin if we already have many open.
    // If this is a new bin (bin_residual == bin_capacity), increase its score 
    // relative to the number of existing open bins to discourage proliferation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // Global efficiency: If the bin is very empty, penalize it to encourage
    // consolidation of smaller items into fewer bins.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily favor bins that leave minimal space
    // We prioritize bins that result in a smaller post_residual (Best Fit).
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the remaining space can accommodate the next item, 
    // reward this bin to prevent fragmentation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: reduction in score proportional to how well the next item fits
            score -= (next_item_size as f64) * 1.5;
            // Additional bonus if it's a "tight" fit for the next item
            if post_residual - next_item_size < 10 {
                score -= 20.0;
            }
        } else {
            // Penalty: if this bin becomes useless for the next item, penalize it
            score += 15.0;
        }
    }

    // 3. Global Efficiency: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, this is a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Heavily penalize opening new bins unless necessary
            score += 60.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 4. Mean Residual Balancing:
    // If this bin's residual is significantly better than the global mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Last Chance Heuristic:
    // If this is the only bin that fits the current item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize tiny residuals (the "Fragment" trap).
    // If post_residual is very small (< 10), it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Coupling: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // 3. Global State: If we are near the end of the stream, prioritize tight packing 
    // to avoid leaving too many bins open.
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. New Bin Logic: If we are considering a new bin (bin_residual == bin_capacity),
    // penalize it heavily unless existing bins result in poor fragments.
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing options are objectively bad (high mean_residual)
        // or if we have very few bins open.
        score += 35.0 + (mean_residual * 0.5) - (open_bins_count as f64 * 0.2);
    } else {
        // Reward bins that bring the mean_residual closer to the item_size,
        // reducing the likelihood of creating "dead" space.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Urgency: If this is the last fitting bin, slightly favor it to avoid 
    // unnecessary bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating 'fragmented' space (small, unusable residuals) that gets worse 
    // as we approach the end of the stream, where packing efficiency is critical.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + progress * 5.0);
    }

    // Lookahead logic: If the next item is large and the current placement creates a 
    // residual that cannot fit the next item, penalize this bin.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 1.5;
    }

    // New Bin Logic: If this is an empty bin (bin_residual == bin_capacity), 
    // only select it if the current best fit is poor.
    if bin_residual == bin_capacity {
        // High penalty for starting a new bin, but scale it down as the stream 
        // progresses to ensure we don't end up with many half-empty bins at the end.
        score += 35.0 * (1.0 - progress * 0.5);

        // If there are many fitting bins, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 10.0;
        }
    } else {
        // If this is an existing bin, favor those that bring the residual 
        // closer to the global mean (balancing load across bins).
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // The core strategy is a "Best-Fit Decreasing" variant combined with harmonic lookahead.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalize opening a new bin heavily unless the current open bins are very full.
        // If we have many open bins, opening a new one is expensive.
        score = 25.0 + (open_bins_count as f64 * 2.0);

        // If the next item is very large, it might be worth opening a new bin now.
        if next_item_size > 70 {
            score -= 15.0;
        }
    } else {
        // Favor placements that leave residuals matching potential future items (harmonic grouping).
        // Penalize residuals that are too small to fit common items (10-20 range).
        if post_residual > 0 && post_residual < 10 {
            score += 40.0; // "Dead zone" penalty
        }

        // Lookahead: if the next item fits into the current post_residual, reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // If this is the only bin that can fit the item, we are forced to take it.
        // We reward it to ensure it is chosen over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Penalty for leaving the bin half-empty (creates fragmentation).
        // We prefer residuals near 0 (perfect fit) or residuals that accommodate next_item_size.
        let fragmentation_penalty = (post_residual as f64 - 25.0).abs() * 0.1;
        score += fragmentation_penalty;
    }

    // Progression scaling: as we near the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype: Strict dead space avoidance with bin pressure.
    // We aim to minimize the post_residual, but heavily penalize values that fall 
    // into the "unusable" range (1..10), as items are rarely smaller than 10.

    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small gaps < 10 are highly undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Lookahead logic: if the next item is large, prioritize keeping the post_residual
    // high enough to accommodate it, or perfectly matching the current item to close the bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0; // Reward bin as a good candidate for the next item
        } else if post_residual > 0 {
            score += 20.0; // Penalize creating a gap that can't fit the next item
        }
    }

    // Open bin pressure: Penalize opening new bins unless the fit is near-perfect.
    // If the bin is new (bin_residual == bin_capacity), increase score based on current open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // Only open a new bin if the fit is very tight (Best-Fit logic)
        score += (100 - item_size) as f64 * 0.5;
    }

    // If this is the last chance to fit the item in an existing bin, favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Normalize against mean_residual to avoid fragmenting bins too early.
    if post_residual < mean_residual as u32 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
