    // As we approach the end, prioritize tight packing (minimizing post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 0.5);

    // 5. Mean residual sensitivity: If the current bin is significantly "emptier" 
