    // Reward bins that leave exactly enough space for the next item (or slightly more)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Heavily reward perfect fits for the next item
            score -= (100.0 - slack as f64) * 1.5;
        } else {
            // Penalize if the next item won't fit in this bin anymore
            score += 25.0;
        }
    }

    // 3. Dynamic load balancing:
    // Prefer bins that stay close to the current mean_residual to avoid fragmented bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. Critical thresholding:
    // If this is the last chance to fit the item in existing bins, prioritize it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 75.0;
    }

    // 5. Progress-dependent scaling:
    // As the stream nears the end, become more conservative about creating new bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (1.0 - progress) * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post-residuals (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for opening new bins: Exponentially increase cost based on progress.
    // We only open a new bin if the existing bins leave no room for the next item.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 150.0 * (1.0 + progress);
        } else {
            score -= 50.0;
        }
    } else {
        // Lookahead heuristic: If the next item fits into the post_residual, 
        // prioritize this bin to maximize packing density.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }

        // Avoid "fragmentation" - if a bin has a very small residual that is likely
        // to be unusable (e.g., < 10), penalize it unless it's a perfect fit (post_residual == 0).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // If this bin is the last one that can fit the current item, 
        // we should favor it to save empty bins for harder items.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Global state balancing: if our mean residual is high, we are being too wasteful.
        // Penalty for bins that keep the mean residual above a certain threshold.
        if mean_residual > 20.0 {
            score += (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) quadratically
    // A residual of 0 is perfect (score 0), a residual of 1-5 is very bad (dead space)
    let dead_space_penalty = if post_residual == 0 { 0.0 } else if post_residual < 10 { 50.0 / post } else { post * 0.1 };

    // Encourage filling bins that are already "tight" to keep open_bins_count low
    // We normalize the residual by the capacity to weight by percentage
    let fill_ratio = 1.0 - (post / bin_capacity as f64);
    let compactness_reward = -15.0 * fill_ratio * (1.0 - progress);

    // Lookahead logic: if next_item_size fits in the post_residual, reward this placement
    let lookahead_reward = if next_item_size > 0 && next_item_size <= post_residual {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decreases as the stream progresses (early on, we prefer reuse over new bins)
    let new_bin_penalty = if bin_residual == bin_capacity {
        40.0 + (20.0 * progress)
    } else {
        0.0
    };

    // Factor in the mean residual: if we are placing into a bin that is much emptier 
    // than the average, we are wasting potential capacity.
    let mean_deviation = (bin_residual as f64 - mean_residual).abs() * 0.2;

    dead_space_penalty + compactness_reward + lookahead_reward + new_bin_penalty + mean_deviation
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing
    // We prioritize bins where the remaining space is small, but not so small it becomes useless.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (20, 25, 33, 50)
    // Residuals that are "clean" are more likely to accommodate future items.
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
        score += harmonic_penalty * 0.5;
    }

    // 3. Lookahead Integration: If the next item fits into the current post_residual, prioritize this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
