    }

    // 4. Strategic New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many 
    // bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.0);
        // Only open a new bin if the current mean residual is already quite tight
        if mean_residual > 15.0 {
            score -= 10.0;
        }
    }

    // 5. Scarcity/Fitting Logic:
    // If this is the last bin that can fit the item, give it a slight boost to keep the packing "dense".
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // 6. Progression Scaling:
    // Towards the end of the stream, prioritize aggressive filling to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": gaps smaller than the minimum likely item (approx 10).
    // If post_residual is in (0, 10), it is highly likely to become unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
