        }
    }

    // Favor bins that align with the mean residual to keep bin states uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize it based on how many existing bins could have taken the item.
    // We want to force usage of existing bins unless they are extremely poor fits.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 25.0;
        score += (open_bins_count as f64) * 2.5;
    } else {
        // 2. Best-Fit logic: prioritize bins where the resulting residual is small.
        // We penalize the post_residual, but modify it based on the next item.

