        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // 5. Urgency: If this is the last bin that can fit the item, give it a slight priority boost
        // to prevent "stranding" items that might need this specific space later.
        if fitting_bins_count == 1 {
