    // If this is a new bin (bin_residual == bin_capacity), apply a high base penalty
    if bin_residual == bin_capacity {
        score += 35.0;
        // If there are other bins that could have fit the item, discourage new bin creation
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Compactness Bias: Prefer bins that already have a lower residual (filling them up)
    // This pushes the algorithm toward Best-Fit behavior
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // 5. Progression Scaling: As the stream nears the end, prioritize finishing existing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (the tighter the fit, the better the score)
    // We keep post_residual as the base, so smaller is naturally better.

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
        // Bonus for "perfect" alignment with next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Fragmentation Control: Penalize creation of "dead zones" (small residuals that cannot fit common items)
    // Assuming typical items are > 10, residuals between 1 and 9 are extremely inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Global Balance: If we are creating a new bin, only do so if the current fitting options are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the existing fitting bins are "too full" or "too empty" on average
        // relative to the current item's requirements.
        if fitting_bins_count > 0 {
            score += 60.0; // Heavy penalty for opening new bins if alternatives exist
        } else {
            score -= 20.0; // Incentive to open a new bin if no other fit is possible
        }
    }

    // 5. Dynamic Density Adjustment: As the stream progresses, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // In the final phase, prioritize filling bins to capacity over opening new ones.
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize tiny residuals (the "fragmentation" trap).
    // If post_residual is small but > 0, it is often a "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // prioritize this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (1.0 - progress);
    }

    // 3. Global State Balancing: If we have many open bins, penalize opening a new one.
    // If fitting_bins_count is low, we are running out of options; prioritize current fit.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to how many bins are already open.
        score += (open_bins_count as f64 * 5.0) + (20.0 * progress);
    } else {
        // Bias towards bins that keep the global mean residual high (keeping bins "fuller").
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 4. Critical Thresholding: If this is the only bin that fits the current item,
    // force selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best-Fit principle)
    // We heavily penalize large post_residuals to keep bins packed tightly.
    let mut score = post * post;

    // Interaction 1: Lookahead influence.
    // If the next item is large, we strongly prefer keeping a larger residual in the current bin 
    // to accommodate it, effectively "saving" space for the next step.
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 - post).max(0.0) * 1.5;
        score += lookahead_penalty * (1.0 - progress);
    }

    // Interaction 2: Global state normalization.
    // As the stream progresses, we become more conservative about opening new bins.
    // We penalize opening a new bin (where bin_residual == bin_capacity) by scaling it with progress.
    if bin_residual == bin_capacity {
        score += 500.0 * (1.0 - progress * 0.5);
    }

    // Interaction 3: Fitting constraints.
    // If this is the only bin that can fit the item, we lower the score to prioritize it 
    // over opening a new bin, but we add a penalty factor based on the mean_residual
    // to avoid creating "dead" bins that are hard to fill later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
        score += mean_residual * 0.5;
    }

    // Interaction 4: Non-linear coupling with open_bins_count.
    // Discourage creating too many fragmented bins early on.
    score += (open_bins_count as f64).powf(1.5) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily favor bins where the residual becomes small.
    // However, avoid "dead space" (residuals < 10) unless it perfectly fits the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Penalty for creating slivers that are hard to fill
    }

    // 2. Lookahead Coupling: If next_item_size is known, reward bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for preserving compatibility for the next item
        } else {
            score += 5.0; // Minor penalty for blocking the next item
        }
    }

    // 3. Harmonic Packing: Favor bin state based on how the post_residual interacts with capacity.
    // This rewards placements that leave a remainder which is a multiple of common item sizes.
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.5;

    // 4. Global Density Control: If we have many open bins, prioritize tighter packing.
    // If we have few open bins, be more willing to open a new one (penalty for open_bins_count).
    score += (open_bins_count as f64) * 0.2;

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // to force the algorithm to prefer existing bins unless the fit is truly terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 45.0; // Discourage opening a new bin if space exists elsewhere
        } else {
            score -= 10.0; // Necessary to open a new bin if no other option exists
        }
    }

    // 6. Progress weighting: In the final stages, tighten the heuristic to minimize new bin openings.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that are too small to be useful
    // (e.g., < 10) but not zero (perfect fit). 
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Open Bins Pressure: Penalize opening a new bin if we have many open bins already.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have other fitting bins, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 3. Lookahead coupling: If a large item is coming next, prioritize leaving space for it.
    // If the current post_residual is too small for the next_item, penalize it slightly.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // 4. Density Balancing: Favor bins that stay close to the current mean_residual.
    // This helps keep bins packed somewhat uniformly.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy (2-step):
    // If next_item_size fits perfectly in the post_residual, reward this bin heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact matches or tight fits for the next item
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - fit_diff) * 2.5;
        } else {
            // If next_item_size cannot fit, penalize the bin slightly to encourage 
            // saving this bin for a smaller item or picking a different bin.
            score += 20.0;
        }
    }

    // 3. Fragmentation Control:
    // If this is the only bin that can fit the item, we are forced to use it.
    // However, if we have a choice, avoid creating "unusable" small gaps.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0; // Strong incentive to use the last fitting bin
    }

    // 4. Global State Awareness:
    // If the mean residual of open bins is already high, be more conservative
    // about opening new bins.
    if bin_residual == bin_capacity {
        // New Bin Penalty: Only open if the current mean residual is already quite low,
        // suggesting that existing bins are full.
        score += 40.0 + (mean_residual * 0.8);
    }

    // 5. Progression Bias:
    // As we approach the end of the stream, prioritize closing existing bins (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
