    // new bin creation (unless the post_residual is extremely poor).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Mean residual coupling:
    // Penalize bins that deviate significantly from the mean residual of open bins
    // to keep the "fill level" of open bins homogeneous.
    let dev = (post - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
