        let after_lookahead = post_residual - next_item_size;
        if after_lookahead < 10 {
            score -= 20.0;
        }
    }

    // 4. Global Density Control: 
    // If we have many open bins, prioritize closing them (lower post_residual).
    // If we have few open bins, we can be more selective.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. New Bin Logic: 
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // Only open a new bin if the average residual of existing bins is already very low (fragmented).
    if bin_residual == bin_capacity {
        if mean_residual < 20.0 && open_bins_count > 0 {
