        // Reward bins that stay close to the global mean residual to keep packing density uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too small for the next item.
    // If the next item exists and won't fit in the post_residual, we penalize the current choice.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // Reward bins that have residuals close to the global mean (balancing density).
    // This helps prevent fragmentation by keeping bins similar in usage.
    let mean_diff = (post as f64 - mean_residual).abs();
    score += 0.5 * mean_diff;

    // Penalty for opening new bins:
    // If bin_residual == bin_capacity, it represents a new bin.
    // We increase the cost of opening a new bin as the stream progresses 
    // to force consolidation in the later stages of the item stream.
    if bin_residual == bin_capacity {
        score += 40.0 + (30.0 * progress);
    }

    // If this is the last fitting bin, we apply a discount to encourage using it
    // rather than opening a new bin, unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - (post / bin_capacity as f64));
    }

    // Non-linear coupling: penalize very small residuals that are likely to become 
    // "orphaned" space that cannot fit any typical item (assuming items > 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

