    // We heavily penalize residuals between 1 and 9 as they are likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic grouping: Favor placements that leave residuals matching potential future items.
    // If the next item can fit in the post_residual, we reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
