    if bin_residual == bin_capacity {
        // Only consider a new bin if the current number of bins is low, 
        // or if we have no good fits (fitting_bins_count is low).
        score += 30.0 + (open_bins_count as f64 * 5.0);
    }

    // 6. Last-Chance heuristic: If this is the only bin that fits the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // Archetype: Multi-variable dynamic residual optimization.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize small residual fragments (Best Fit Decreasing variation)
    // We prioritize bins where the post-fit residual is small, but not too small 
    // to prevent unusable gaps (e.g., < 10 units).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - progress);
    }

    // 2. Lookahead Integration: If next item fits in the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // 3. Global State Balancing: Use mean_residual to penalize bins that deviate from the average.
    // Keeping bins balanced prevents "fragmentation traps".
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. New Bin Logic: Discourage opening a new bin unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the fit is terrible.
        // Penalty scales with how many bins are already open to encourage consolidation.
        score += (open_bins_count as f64 * 5.0) + (100.0 * (1.0 - progress));
    } else {
        // If this is the last bin that can fit the item, give it a significant bonus
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Penalize bins that create "dead space" (e.g., residual > 50) 
        // especially when the item size is large.
        if post_residual > 50 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
