    // We want to minimize post_residual, so we start with it.
    let mut score = post;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), we apply a dynamic penalty
    // that decreases as we reach the end of the stream, encouraging density early on.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 25.0);
    } else {
        // Reward fitting into bins that are already tight, especially if only one bin fits.
        // If fitting_bins_count is 1, this is the only bin that can take the item.
