    }

    // Interaction with mean_residual: favor bins that help keep the global 
    // mean_residual low to maintain a balanced packing distribution.
    score += (post - mean_residual).abs() * 0.5;

    // Final non-linear coupling: penalize high open_bins_count as the stream progresses
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
