    // 3. Lookahead Logic
    // If we have a next_item, prioritize bins that can accommodate it later.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // If we can't fit the next item, penalize proportionally to the wasted opportunity
            score += (next_item_size - post_residual) as f64 * 0.5;
