    }

    // 4. New Bin Thresholding
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to (fitting_bins_count == 0)
        // or if the progress is late and we want to consolidate.
        if fitting_bins_count > 0 {
            score += 60.0 + (progress * 40.0);
        } else {
            score -= 10.0;
        }
    }

    // 5. Global Density Balancing
    // If the mean residual is high, we are being too loose; prioritize tighter fits.
    if mean_residual > 30.0 {
