        // High penalty for opening new bins early in the stream.
        // Opening a new bin is only attractive if existing bins are poorly utilized (mean_residual > 30).
        score = 100.0 + (mean_residual * 2.0) + (progress * 50.0);
    } else {
        // If this bin is the only one that can fit the item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Penalize bins that deviate significantly from the mean_residual to promote uniformity.
        score += (post_res - mean_residual).abs() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a heavy penalty based on current open bin count
    // to encourage filling existing bins before expanding.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 1.5);
    } else {
        // 2. Harmonic Class Logic: penalize post_residual values that are "unusable"
        // (too small for most incoming items, e.g., < 10).
        if post_residual < 10 {
            score += 25.0;
        }

        // 3. Lookahead: if the next item is large, favor bins that can accommodate it.
        // We calculate the "fit gap" for the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Reward bins that can fit the next item
            } else {
                score += 10.0; // Penalize bins that leave no room for the next item
            }
        }

        // 4. Fitting constraints: If this is the only bin that fits the current item,
        // reduce the score to force the selection of this bin.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // 5. Mean-based balancing: If this bin is significantly below the average
        // fill, it is a "good" bin to fill up.
        if (bin_capacity - bin_residual) < (bin_capacity as f64 - mean_residual) as u32 {
            score -= 5.0;
        }
    }

    // 6. Final progression bias: as the stream nears the end, become more aggressive
    // about fitting items into existing gaps to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-20)
    // If post_residual is in (0, 10), it is highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins unless necessary.
    // If it's a new bin (bin_residual == bin_capacity), apply a heavy penalty based on existing open bins.
    if bin_residual == bin_capacity {
