    // 4. Fitting Density: If this is the only bin that fits the item, reward it to prevent premature new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Global Balance: Penalize bins that deviate too far from the mean_residual (maintains homogeneous bin filling).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual.
    // The base score is already post_residual.

    // 2. Penalize opening a new bin prematurely.
    if bin_residual == bin_capacity {
