    if (bin_residual as f64) > mean_residual {
        score += 10.0;
    }

    // 5. Efficiency scaling based on stream progression.
    // In later stages, be more aggressive about filling existing bins to minimize bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    // 6. Avoid "fragmentation traps" (very small residuals that can't fit anything).
    // If post_residual is < 10 (smallest possible item size), treat as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

