pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the creation of a new bin (bin_residual == bin_capacity) 
    // more heavily as the stream progresses, to encourage consolidation.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (25.0 + (progress * 50.0));

    // Best-Fit Decreasing logic: Favor bins where the post_residual is smallest.
    // We add a non-linear penalty for larger residuals to keep bins tight.
    let residual_penalty = post * post / 20.0;

    // Lookahead logic: If a bin can fit both the current item and the next item,
    // reward it. If the current bin is the only one left that can fit the item
    // (fitting_bins_count == 1), we apply a slight discount to avoid opening a new bin.
    let fit_bonus = if next_item_size > 0 && (post_residual >= next_item_size) {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    let urgency_bonus = if fitting_bins_count == 1 && is_new_bin == 0.0 {
        -10.0
    } else {
        0.0
    };

    // Combine factors:
    // 1. residual_penalty: promotes Best-Fit
    // 2. new_bin_penalty: discourages premature bin opening
    // 3. fit_bonus: encourages pairing items
    // 4. urgency_bonus: keeps filling existing bins until forced to open new ones
    residual_penalty + new_bin_penalty + fit_bonus + urgency_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #276: Harmonic-Residual Coupling
    // Objective: Minimize fragmentation by prioritizing tight fits (Best-Fit) 
    // while penalizing the creation of "orphan" gaps that cannot accommodate the next known item.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for leaving a gap that is too small for any future item
    // If the post_residual is smaller than the minimum likely size (assumed ~10),
    // we penalize it unless it is exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead logic: If a next item exists, penalize bins that cannot fit it
    // effectively creating a "Next-Fit-Lookahead" bias.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize leaving a gap that can't fit the next item
            score += 15.0 * (1.0 - progress);
        } else {
            // Reward bins that remain capable of holding the next item
            score -= 10.0 * (1.0 - progress);
        }
    }

    // 3. Harmonic class alignment:
    // Favor bins that result in a post_residual that is a multiple of common item sizes (20, 25, 33)
    // This maintains "clean" remaining space for future packing.
    let remainder = post_residual % 25;
    if remainder == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // 4. Thresholding: Avoid opening a new bin if possible
    // If this is a new bin call (bin_residual == bin_capacity), increase cost
    // unless open_bins_count is very low (initial phase).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // High penalty for opening a new bin unless we are in the early stage
        score += 40.0 * (1.0 - progress * 0.5);
    }

    // 5. Fitting count sensitivity:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

