    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Urgency: As we approach the end of the stream, prioritize closing existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
