        score += (open_bins_count as f64 * 2.0) + (progress * 50.0);
    } else {
        // If we have very few fitting bins, prioritize this bin to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Lookahead: If next_item_size is large, avoid leaving a residual that cannot fit it.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Balance global mean residual: penalize bins that deviate significantly from the mean.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residuals (Best Fit logic)
    // We want post_residual to be as close to 0 as possible.
    let mut score = post;

    // Penalty for creating a "fragment" (a bin that is almost empty but not quite)
    // This is especially bad if we are near the end of the stream (progress -> 1.0)
    if post > 0.0 {
        score += (1.0 - (post / bin_capacity as f64)).powf(2.0) * 10.0 * progress;
    }

    // Lookahead logic: if the next item fits into the post_residual, 
    // we should prioritize this bin significantly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (bin_capacity as f64 - post) * 0.5;
    }

    // If this is the only bin that fits the current item, avoid opening a new bin
    // unless the current fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize new bins (bin_residual == bin_capacity) increasingly as the stream progresses
    // to force consolidation of items into existing bins.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 60.0);
    }

    // Influence of existing bin distribution: 
    // If our mean residual is high, we are under-utilizing bins, 
    // so we should be more aggressive about filling tighter (penalize higher post_residual).
    score += (mean_residual / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #286: Harmonic-Residual Balancing
    // We aim to minimize post_residual while penalizing "dead zones" that cannot fit future items.

    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too small for common items (dead space < 10)
    // If post_residual is in (0, 10), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If the next item cannot fit in this post_residual, 
    // penalize proportionally to how much space is left (fragmentation).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.5;
    }

    // Harmonic preference: Favor bins that leave residuals which are multiples of 20 
    // (creating "slots" for items 20, 40, 50, etc).
    let rem = post_residual % 20;
    if rem == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // If this is the last chance for the current item (fitting_bins_count == 1),
    // and the bin is nearly full, we force the fit by lowering the score.
    if fitting_bins_count == 1 && post_residual < 15 {
        score -= 10.0;
    }

    // If considering a NEW bin (bin_residual == bin_capacity), 
    // only choose it if the average residual of current bins is already very low (high fragmentation).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 25.0 {
            score += 10.0; // Discourage new bins if we have space elsewhere
        } else {
            score += 40.0; // Heavily penalize opening new bins unless necessary
        }
    }

    // Progression scaling: As we reach the end of the stream, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

