    // 3. Global state awareness: If we are near the end of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 15 {
        score -= 10.0;
    }

    // 4. Fitting constraints: If this is the only bin that can fit the current item, 
    // it is highly desirable to use it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Empty bin penalty: Discourage opening new bins unless the fit is perfect or necessary.
    // The "new bin" candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins already, make opening a new one even more expensive.
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Balance the bin usage by penalizing bins that deviate significantly from the mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow flexibility as the stream ends.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 150.0 + 20.0
    } else {
        0.0
    };

    // Calculate how 'tight' the fit is. Smaller post_residual is usually good (Best Fit),
    // but we want to avoid leaving tiny gaps that are hard to fill (e.g., 1-9 range).
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        25.0 * (1.0 - (post / 10.0))
    } else {
        0.0
    };

    // Lookahead interaction: if next_item_size is large and we are creating a small post_residual,
    // we might regret this placement.
    let lookahead_penalty = if next_item_size > 0 && (next_item_size as f64) > post && post > 0.0 {
        (next_item_size as f64 - post) * 0.5
    } else {
        0.0
    };

    // Favor bins that align with the current global mean to keep the system balanced.
    let balance_score = (post - mean_residual).abs() * 0.1;

    // Combine factors. Lower score is better.
    // We prioritize bins that result in a tight fit (low post) but avoid the "dead zone" (fragmentation).
    post + fragmentation_penalty + new_bin_penalty + lookahead_penalty + balance_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
