    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating small, unusable gaps (1-9) which are hard to fill
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Reward bins that become "tight" (residual near 0)
    let tightness_reward = -1.5 * (100.0 - post_res).sqrt();

    // Lookahead logic: if the next item fits better in this bin's post_residual, prioritize it.
    // This reduces the chance of needing a new bin later.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -20.0 * (next_item_size as f64 / post_res)
    } else {
        0.0
    };

    // Adaptive pressure: as the stream nears the end, be more aggressive about filling bins 
    // to minimize the total count of open bins.
    let exhaustion_pressure = (progress * 50.0) * (open_bins_count as f64 / 10.0);

    // If this is a new bin, penalize it heavily early on, but less as we run out of space.
    let new_bin_penalty = if bin_residual == bin_capacity {
        40.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Base score is the residual; we want to minimize this, but we apply non-linear
    // modifiers to prioritize "best-fit" over "first-fit".
    let mut score = post_res + fragmentation_penalty + tightness_reward + lookahead_bonus + exhaustion_pressure + new_bin_penalty;

    // Favor bins that have residuals close to the global mean to maintain uniformity.
    score += 0.5 * (post_res - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
