pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (residuals too small for common items)
    // If post_residual is in the range (0, 10), it is very hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If the current post_residual is too small for the next item, penalize.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0 * (1.0 - progress);
        } else {
