    // 3. Global State: Discourage opening new bins early in the stream.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Strong penalty for opening a new bin if others exist
            score += 60.0 * (1.0 - progress * 0.5);
        }
    } else {
        // 4. Tightness: Reward bins that are becoming "fuller" (Best-Fit logic)
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Emergency logic: If this is the only bin that fits the item, 
    // prioritize it to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Balance: Avoid creating extreme variance in residuals across open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
