        // Opening a new bin early is fine, late in the stream it's costly.
        score += 25.0 + (step_index as f64 / total_items as f64) * 50.0;
    } else {
        // Reward bins that bring the residual closer to the global mean (homogenization).
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score -= residual_diff * 0.1;
    }

    // 4. Critical Threshold: If this is the last bin that can fit the item,
