        let secondary_post = post_residual - next_item_size;
        if secondary_post < 5 {
            score -= 15.0;
        }
    }

    // 4. Density Balancing:
    // If fitting_bins_count is 1, this is the only bin that can take this item.
    // We must prioritize this bin to avoid opening a new one, unless the fit is atrocious.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Progression Scaling:
    // As we reach the end of the stream, prioritize closing bins (lower mean_residual)
    // to reduce the total number of active bins.
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

