    // Gaps between 1 and 9 are extremely dangerous (unusable for items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the current post_residual,
    // lower the score to prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
