    }

    // 4. Global Packing Efficiency: If this bin's residual after placement is worse than the
    // current mean residual of other open bins, penalize it to keep packing density uniform.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
