    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 10.0;
    }

    // Dynamic scaling based on stream progression to encourage tighter packing in later stages.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin prematurely
    if bin_residual == bin_capacity {
        score += 45.0; // High barrier for new bins
        if fitting_bins_count > 0 {
            score += 30.0; // Penalty multiplier if better fits exist
        }
    }

    // 2. Lookahead: Reward bins that perfectly accommodate the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // Very high priority for perfect fit
        } else if post_residual > next_item_size {
            // Reward bins that leave exactly enough space for next_item_size + buffer
            score -= (post_residual as f64 - next_item_size as f64) * 0.2;
        } else {
            // Penalize bins that would be too small for the next item
            score += 15.0;
        }
    }

    // 3. Density balancing: Avoid fragmenting bins too far from the mean
    // We prefer bins that stay close to the global mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.15;

    // 4. Scarcity: If this is the last fitting bin, prioritize it to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression adjustment: Become more aggressive as the stream ends
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-residual (Best Fit principle).
    // Lower post_residual means a tighter fit, which is generally better.
    let mut score = post_residual as f64;

    // Penalty for creating "fragmented" space (small, unusable residuals).
    // If post_residual is small (e.g., < 10) but > 0, it's often a "dead space" trap.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if we know the next item, penalize bins that cannot fit it 
    // after the current placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Dynamic pressure: If fitting_bins_count is low, we are running out of options.
    // If fitting_bins_count == 1, this is the last chance for this item in an existing bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Global state awareness: If we have many open bins, prioritize closing them 
    // by filling them up (lower post_residual).
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.5;
    }

    // New-bin logic: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only open a new bin if the current "tightest fit" is still very poor (high post_residual).
    if bin_residual == bin_capacity {
        // High cost to open a new bin unless the remaining space in existing bins is 
        // significantly worse than the capacity of a fresh bin.
        score = 65.0 + (mean_residual * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize values below the expected next item size (approximated by 100 - mean_residual).
    let expected_next = 100.0 - mean_residual;
    if post_res < expected_next {
        score += (expected_next - post_res).powf(1.5);
    }

    // Dynamic pressure: As the stream progresses, we become more conservative about opening new bins.
    // If it's a new bin (bin_residual == bin_capacity), increase cost based on stream progress.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 + progress.powi(2));
    }

    // Lookahead coupling: If a next item exists, penalize residuals that are too small to fit it.
    if next_item_size > 0 {
        if post_res > 0.0 && post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res) * 2.0;
        }
    }

    // Reward bins that have residuals close to the global mean, promoting uniform bin utilization.
    let dev_from_mean = (post_res - mean_residual).abs();
    score += dev_from_mean * 0.5;

    // If this is the last fitting bin, slightly lower the score to prioritize filling it 
    // rather than opening a new one, unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (post_residual < 10, but not 0)
    // Small residuals are usually bad unless they are 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Class Logic: Reward filling bins to specific thresholds
    // If we can fit the next item into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Pressure management: If we are running out of bins or late in the stream, 
    // be more aggressive about closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * 0.5 * progress;

    // 4. Penalty for opening new bins: 
    // If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of current bins is very high (wasteful).
        // Otherwise, penalize the new bin heavily.
        score += 35.0 + (mean_residual * 0.2);
    }

    // 5. Lookahead coupling: If this is the last chance for the current item, 
    // reduce the penalty for a poor fit to avoid fragmenting remaining space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Modulo-based "sweet spot" targeting:
    // Try to keep post_residual near multiples of 20 to accommodate common item sizes.
    let remainder = post_residual % 20;
    if remainder > 15 || remainder == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that are too small to fit typical items (< 10)
    // but large enough to be considered wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many 
    // bins are already open to favor consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If there are bins that can already fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
