    // 4. Tight Fit Reward: Heavily prioritize bins that are nearly filled by the current item.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 5 {
        score -= 15.0;
    }

    // 5. Global Efficiency: As we approach the end of the stream, prioritize closing bins
    // by rewarding placements that lead to very small residuals.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

