    // Apply a penalty for leaving small, unusable gaps (1..9) which are hard to fill.
    // This is weighted by progress to be more aggressive towards the end of the stream.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + progress * 2.0);
