    }

    // Penalize opening a new bin (bin_residual == bin_capacity) progressively.
    // As the stream progresses, we want to be more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress * 0.5);
    }

    // Coupling with global state: penalize creating a bin that deviates significantly
    // from the current mean residual, promoting uniform bin density.
    let density_deviation = (post - mean_residual).abs();
    score += density_deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
