    }

    // 3. Harmonic/Modulo optimization: Prefer filling bins to specific "safe" thresholds (e.g., 0, 25, 50).
    // If post_residual is a multiple of 25, it is statistically more likely to fit subsequent items.
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin fits well.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many fitting options.
        score += 20.0 + (fitting_bins_count as f64 * 5.0);
    }

    // 5. Mean residual balancing:
    // Avoid leaving bins significantly emptier than the average, as this wastes capacity.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 6. Progressive tightening:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
