    // 3. Global state: If we are late in the sequence, become more aggressive 
    // about filling existing bins to minimize the total count.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on
    // how many other bins could have accepted the current item.
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting bins are "bad" fits (resulting in large dead zones)
        // or if we have very few open bins.
        score += (fitting_bins_count as f64) * 25.0;

        // Dynamic threshold to prevent opening too many bins too early
        if open_bins_count > 0 && progress < 0.9 {
            score += 30.0;
        }
    }

    // 5. Mean residual balancing:
    // Avoid bins that deviate significantly from the mean state of the system.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow more flexibility as we near the end
    let open_new_penalty = if bin_residual == bin_capacity {
        (1.0 - progress) * 150.0 + 20.0
    } else {
        0.0
    };

    // Reward placements that leave a residual which can accommodate the next item (lookahead)
    let lookahead_bonus = if next_item_size > 0 && post >= next_item_size as f64 {
        -15.0 * (1.0 - (post - next_item_size as f64) / 100.0)
    } else {
        0.0
    };

    // Penalize small "sliver" residuals that are unlikely to fit future items (1-9 range)
    let sliver_penalty = if post < 10 && post > 0 {
        100.0 / (post + 1.0)
    } else {
        0.0
    };

    // Favor bins that are already closer to being filled to consolidate space
    // Use the deviation from mean_residual to avoid fragmentation
    let consolidation_score = (post - mean_residual).abs() * 0.1;

    // Favor bins that are the only option (fitting_bins_count == 1) to prevent premature new bin opening
    let last_chance_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -50.0
    } else {
        0.0
    };

    let score = post + open_new_penalty + lookahead_bonus + sliver_penalty + consolidation_score + last_chance_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
