    // 4. Global state coupling: If the current bin's residual is significantly 
    // better (closer to the mean) than the average, favor it to keep bin states uniform.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. If fitting_bins_count is 1 and this is that bin, prioritize it to 
    // avoid stranding items that have no other home.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base heuristic: Best Fit (minimize post_residual)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: dynamic based on progress
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        // Penalty scales with the average capacity wasted in existing bins
        // If we have many open bins with high residuals, opening a new one is very bad.
        score += 100.0 * (1.0 - progress) + (mean_residual * 1.5);
    } else {
        // Reward bins that leave space for the next item (Lookahead heuristic)
        // If the next item fits into the post_residual, we prioritize this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }

        // Avoid "fragmentation traps": 
        // Penalize residuals that are too small to fit common items (e.g., < 10)
        // but large enough to be wasted space.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0 * (1.0 - progress);
        }

        // If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Interaction term: Coupling residual variance with progress
    // Penalize large residuals more heavily as we near the end of the stream
    score += (bin_residual as f64 - mean_residual).abs() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Harmonic penalty: small residuals are often "trapped". 
    // If post_residual is < 10 (too small for most items), penalize heavily.
    if post_residual > 0 && post_residual < 10 {
