    }

    // 3. Lookahead synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 4. Fitting constraints: If this is the only bin that fits the current item, 
    // prioritize it over opening a new bin (which has residual = 100).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global state normalization: If the bin is very empty (new bin candidate),
    // add a base penalty that scales with the number of open bins to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64 * 2.5);
    }

    // 6. Harmonic refinement: modulo arithmetic on residual to avoid specific "bad" gaps
    // Gaps near 20-30 are often problematic for items of size 40-50.
    if post_residual % 25 < 5 {
        score += 5.0;
    }

    // 7. Progression factor: As we approach the end of the stream, prioritize 
    // filling existing bins more aggressively to minimize trailing orphans.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
