    let fill_intensity = 1.0 + (progress * 5.0);
    score *= fill_intensity;

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // We scale this penalty by the number of open bins to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // Correction for the "last chance" bin: if this is the only bin that fits, 
