        // If fitting_bins_count is high, we have options; keep this score neutral.
        // If fitting_bins_count is 1, this is a "forced" bin; reward it to prioritize filling it.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Progress weighting: In late stages, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
