            // If the current bin cannot fit the next item, penalize it slightly 
            // unless it's a perfect fit (post_residual == 0).
            if post_residual == 0 { -10.0 } else { 5.0 }
        } else {
            // If it can fit, we reward it to keep the "good" bin available.
            -2.0
        };
        score += lookahead_penalty;
    }

    // 4. New Bin Threshold:
    // Opening a new bin is expensive. We only do it if the existing bins 
    // force a "bad" fit (e.g., leaving a large, unusable gap).
    if is_new_bin {
        // Only open a new bin if the existing fits are statistically poor.
        // We use mean_residual to judge the quality of current packing.
        if fitting_bins_count > 0 && mean_residual > 20.0 {
