    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate call.
        // We add a penalty proportional to the number of open bins and progress.
        // Higher progress means we want to consolidate, so opening a new bin gets expensive.
        score += 40.0 + (progress * 60.0) + (open_bins_count as f64 * 5.0);
    } else {
        // Reward placements that bring the bin residual closer to the mean_residual of other bins,
        // which helps in keeping bin utilization balanced.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // If this is the only bin that can fit the item, give it a massive bonus
    // to prevent the heuristic from preferring a new empty bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
