}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual
    // We already have post_residual in the score.

    // 2. Harmonic Penalty for "Dead Space": 
    // If we leave a small residual (e.g., 1-9), it is often unusable. 
    // Penalize residuals that are smaller than the smallest possible item (10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 3. Lookahead Synergy:
    // If the next item can fit in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // 4. Thresholding for New Bins:
    // Only open a new bin if the current fit is "bad" (e.g., post_residual is large)
    // and we have many open bins already.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin could fit it
            score += 100.0 + (mean_residual * 2.0);
        } else {
            // Otherwise, keep it neutral
            score += 40.0;
        }
    }

    // 5. Harmonic Class dampening:
    // Favor bins that push the post_residual towards a multiple of 20, 
    // as these are common item size divisors in balanced distributions.
    let remainder = post_residual % 20;
    if remainder > 15 {
        score += (remainder - 15) as f64 * 2.0;
    } else if remainder < 5 && post_residual > 0 {
        score -= 5.0;
    }

    // 6. Progressive stream pressure:
    // As we approach the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
