    if is_new_bin {
        // Penalty for opening a new bin: higher when many bins are already open or we are near the end.
        // We only open a new bin if the "Best Fit" in existing bins is extremely poor.
        score = 85.0 + (open_bins_count as f64 * 0.5) + (progress * 20.0);
    } else {
        // Reward bins that leave residual space that is likely to fit the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // High priority: fit current AND next
            } else if post_residual < 10 {
                score -= 25.0; // Perfect fit: minimize fragmentation
            }
        }

        // Penalize bins that create "dead zones" (too small for any item, i.e., < 10).
        if post_residual > 0 && post_residual < 10 {
            score += 40.0; 
        }

        // Dynamic pressure: If few bins can fit the item, prioritize keeping current bins open
        // to avoid opening a new one later.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Favor bins that align with the global average residual to maintain uniformity.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
