    // Minimizing post_residual encourages packing tightly.
    let mut score = post;

    // Penalty for creating small, unusable gaps (1..9). 
    // We penalize post_residuals that are too small to fit the smallest expected items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead: If next_item exists, penalize bins that cannot fit it, 
    // but only if we have other bins that might accommodate it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
