        score += 25.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // Reward bins that bring the current bin's residual closer to the global mean_residual.
        // This balances the load across existing bins.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // If this is the last chance to fit the item in an open bin, apply a strong discount.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
