    // unless the current open bins are extremely inefficient.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0) + (mean_residual * 0.5);
    } else {
        // 2. Harmonic Best-Fit logic: penalize post_residuals that are small but not zero (fragmentation).
        // A post_residual of 0 is ideal (perfect fit).
        if post_residual > 0 && post_residual < 10 {
