    // expected items (often ~10-15), it creates "fragmentation". 
    // We penalize post_residual values in the (0, 10) range heavily.
    if post_residual > 0 && post_residual < 12 {
        score += 50.0 + (12.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bins Pressure: If we have many open bins, prioritize closing them by
    // filling them as much as possible (Best Fit behavior).
    score += (open_bins_count as f64) * 0.5;

    // 3. Lookahead Optimization: If the next item exists, penalize placements that
    // leave a post_residual smaller than the next item size.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 4. New Bin Thresholding: If this is an empty bin (bin_residual == bin_capacity),
    // only choose it if the current best existing bin is extremely inefficient.
    // We add a "tax" on opening new bins based on the current mean_residual.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual;
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item,
    // strongly incentivize picking it to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals to keep bins tight.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead matching: If the post_residual can accommodate the next item, 
    // heavily reward this bin to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
