            score += 50.0 + (step_index as f64 / total_items as f64) * 50.0;
        }
    }

    // 4. Mean residual balancing:
    // Penalize bins that deviate significantly from the mean residual to encourage uniform packing.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Critical threshold:
    // If post_residual is very small (e.g., < 5), it's likely "dead space" that cannot
    // fit future items. Penalize this slightly to favor slightly larger residuals
    // that might accommodate future items.
    if post_residual > 0 && post_residual < 8 {
