    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest post_residual
    // (Already captured by the base score = post_residual)

    // 2. Lookahead Penalty: If the next item is large and won't fit the current post_residual, 
    // penalize the choice to keep the residual small.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 25.0 * (1.0 - progress);
    }

    // 3. Fragmentation Penalty: If the post_residual is small but unusable (e.g., < 10), 
    // it creates "dead space". Penalize this.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global State Awareness: If we have many open bins, we should be more aggressive 
    // about filling them rather than opening new ones.
    if is_new_bin {
        if open_bins_count > 0 {
            // Penalize opening a new bin if we have existing capacity
            score += 45.0 * (1.0 - (mean_residual / bin_capacity as f64));
        }
    } else {
        // Reward using existing bins if they are close to the mean residual
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= 5.0 * (1.0 - deviation / bin_capacity as f64);
    }

    // 5. Critical Threshold: If this is the last fitting bin, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0;
    }

    // 6. End-of-stream optimization: As we approach the end, the penalty for opening 
    // a new bin should be higher to force consolidation.
    if is_new_bin {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
