    } else {
        // Favor bins that align with the global mean residual to keep packing uniform
        let mean_diff = (post - mean_residual).abs();
        score += mean_diff * 0.5;
    }

    // If this is the only bin that fits, prioritize it heavily to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
