    // 2. Harmonic Penalty: Penalize residuals that cannot fit common item sizes (e.g., < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 45.0;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
    }

    // 4. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. Global Constraint: If this is the only fitting bin, accept it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. New Bin Thresholding: Penalize opening a new bin heavily unless the current open bins are very full.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already small (compactness high)
        if mean_residual > 25.0 {
            score += 60.0;
        } else {
            score += 120.0; 
        }
    }

    // 7. Dynamic Scaling: As the stream progresses, prioritize tight packing over lookahead.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

