            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - fit_diff) * 0.5;
        } else {
            // Penalize creating a bin that is too small for the next item
            score += 20.0;
        }
    }

    // 4. Balance across open bins: avoid bins that deviate too far from the current mean
    // This encourages keeping the density of all bins somewhat uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Progression awareness: tighten constraints as the stream nears completion
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
