    // Density optimization:
    // Penalize creating high-residual bins when we have many open bins,
    // but allow it if it helps achieve a better fit for the current item.
    // We use the mean_residual to identify if we are currently "wasting" space.
    let residual_diff = (post - mean_residual).abs();
    score += 0.2 * residual_diff * (open_bins_count as f64 / 10.0);

    // Criticality correction:
    // If this is the only bin that can fit the item (fitting_bins_count == 1),
