    // 1. Best-Fit Penalty: Penalize large post-residuals to favor tight packing.
    // We add a non-linear weight to the residual to prioritize filling bins near capacity.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy (Harmonic Coupling): 
    // If next_item_size fits in the remaining space (post_residual), reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual as f64) * 2.5;
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic Fragmentation Control:
    // If post_residual is small but > 0, it creates "dead space". 
    // We penalize residuals that are too small to fit common items (e.g., < 20).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 / (post_residual as f64 + 1.0);
    }

    // 4. Global State Awareness:
    // If this is the only bin that can fit the item, we lower its score to ensure it is picked
    // over opening a new bin (which has a high penalty).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Constraint:
    // When evaluating a new bin (bin_residual == bin_capacity), apply a heavy penalty.
    // The penalty decreases as the stream progresses, allowing for more "fresh" bins 
    // near the end to avoid forcing bad fits into almost-full, awkward bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 65.0 * (1.0 - progress * 0.5);
    }

    // 6. Mean Residual Balancing:
    // Favor bins that align with the current global mean to maintain bin uniformity.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that fall in the "unusable" range (1-9).
    // If a bin has a small remaining gap, it is highly likely to become permanent waste.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bin Pressure: Discourage opening new bins if we have many already, 
    // unless the fit is perfect (post_residual == 0).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (open_bins_count as f64) * 5.0;
    }

    // 3. Lookahead Sensitivity: If the next item is large, favor bins that leave 
    // enough room for it, or minimize the post_residual to keep space contiguous.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that will definitely force a new bin for the next item
            score += 15.0;
        } else if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
            // Reward bins that create a "perfect" landing zone for the next item
            score -= 20.0;
        }
    }

    // 4. Mean Residual Balancing: Prefer bins closer to the global mean to keep 
    // the distribution of fill levels uniform across open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Fitting Bin Urgency: If this is the only bin that can fit the item, 
    // lower the score to prioritize filling it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward tight packing: If the current item leaves very little space, it's a good fit.
    // 2. Lookahead synergy: If post_residual is close to the next_item_size, prioritize this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
    }

    // 3. Penalty for "orphaning": If this is the last bin that can fit the item, 
    // we should be more willing to accept it even if the fit is suboptimal.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // 4. Entropy control: Discourage opening new bins unless the current bin 
    // residual is significantly worse than the global mean residual.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += mean_residual * 1.5;
        }
    } else {
        // Favor bins that keep the residual closer to the mean of other bins
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Progress-based scaling: As the stream nears completion, become more aggressive
    // about packing into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave very small, unusable gaps (1-9)
    // Small gaps are usually wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (post_residual as f64 * 2.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // Further reward if it fills the bin almost perfectly
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 3. New Bin Thresholding: Dynamic resistance to opening new bins.
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
        // Only open a new bin if we have many open bins already (avoiding fragmentation)
        if open_bins_count < 3 {
            score += 40.0;
        }
    }

    // 4. Global State Awareness:
    // If we have many open bins with low mean_residual, try to use the ones that are already 'fuller'.
    if mean_residual < 20.0 && post_residual > mean_residual as u32 {
        score += 15.0;
    }

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it heavily
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post;

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on progress.
    // As the stream progresses, opening new bins becomes increasingly expensive.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 + progress.powf(2.0));
    } else {
        // Reward bins that leave space matching the likely next item size.
        // This is a non-linear coupling: we penalize residuals that are slightly too small 
        // to fit the next item, but reward residuals that fit the next item perfectly.
        if next_item_size > 0 {
            let diff = (post as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.5;

            // Penalty for leaving a "dead zone" (1-9 space) that is hard to fill.
            if post > 0.0 && post < 10.0 {
                score += 15.0 * (1.0 - progress);
            }
        }
    }

    // Penalize increasing the number of bins if we have many fitting options.
    // This forces the algorithm to utilize existing bins more aggressively.
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        score -= (fitting_bins_count as f64).ln() * 5.0;
    }

    // Interaction term: If the bin is nearly empty, penalize it if the mean_residual 
    // of all bins is already high, to prevent "fragmentation" of empty space.
    if post > (bin_capacity as f64 * 0.7) {
        score += mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
