    score += post_residual as f64 * 1.2;

    // 2. Harmonic Class/Modulo logic:
    // Penalize residuals that are "useless" (too small to fit typical future items).
    // If post_residual is < 10, it is likely dead space.
    if post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead coupling:
    // If next_item_size can fit into the new post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Scarcity/Open Bins logic:
    // Discourage opening too many bins if we have plenty of open ones.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0);
        // Heavily penalize opening a new bin if other bins could have fit the item.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 5. Progression scaling:
    // As we reach the end of the stream, tighten the fit requirement.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    // 6. Mean residual balancing:
    // If this bin's residual after placement is worse than the current mean, penalize it.
    if (post_residual as f64) > mean_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // If post_residual is in the range (0, 10), it is highly likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10.0 - post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when many are already active.
    // If we are evaluating a new bin (bin_residual == bin_capacity), increase its cost
    // proportionally to how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean Residual Balancing: Favor bins that keep the overall average residual high (more flexible),
    // but avoid extreme outliers that waste too much space.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.5;

    // 6. Progressive Tightness: As the stream progresses, prioritize tighter fits (lower post_residual)
    // to ensure we aren't left with too many sparse bins at the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "micro-gaps" that are unlikely to fit future items.
    // If post_residual is small but > 0, it's often better to have 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead matching: reward bins where the post_residual can perfectly fit the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that have "just enough" space for the next item.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // 3. Balance: penalize opening new bins unless the current options are very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the average residual is already quite low (forcing consolidation).
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 15.0;
        } else {
            score += 50.0; // High penalty for starting a new bin unnecessarily.
        }
    }

    // 4. Fitting urgency: if this is the last bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 5. Progression: As the stream nears the end, prioritize tightly packing remaining space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (1..9 is useless for most items)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead logic: If a future item fits perfectly or near-perfectly in the current post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 40.0; // Strong reward for creating a perfect fit for the next item
        } else if post_residual < next_item_size {
            score += 20.0; // Penalty if this bin cannot accommodate the next known item
        }
    }

    // 3. Dynamic Thresholding: As we reach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 4. Global State Balancing: Avoid opening too many bins early if residuals are high
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin if we have many open bins with capacity
        if open_bins_count > 0 && mean_residual > 30.0 {
            score += 60.0;
        }
        // If it's the only option, don't penalize too heavily
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // 5. Prefer tighter fits (Best Fit principle)
    // Reward bins that have less space to begin with, but avoid the 1-9 danger zone
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We apply a non-linear penalty to small residuals that are too small to fit the next item
    // but large enough to waste space (the "fragmentation trap").
    let mut score = post;

    // Penalty for creating a bin that is almost empty, but only if we are early in the stream
    // and have plenty of capacity elsewhere.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress to discourage 
        // unnecessary bin creation as the stream nears completion.
        score += (bin_capacity as f64 * 0.75) * (1.0 - progress * 0.5);
    } else {
        // If we are placing in an existing bin, check if we create a "dead" residual
        // that is too small for the next item (lookahead coupling).
        if next_item_size > 0 && post < next_item_size as f64 {
            // Heavily penalize placements that create fragments smaller than the next item
            // unless that bin is already nearly full.
            let fragmentation_penalty = (next_item_size as f64 - post) * 2.5;
            score += fragmentation_penalty * (1.0 - progress);
        }

        // Reward bins that align with the mean_residual to keep bins balanced
        // This prevents creating one "very full" bin and many "very empty" bins.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Encourage using bins that are the "last chance" to avoid opening new ones
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Smooth transition: penalize high open bin counts to encourage compaction
    score += (open_bins_count as f64).powf(1.2) * 0.5;

    score
}

