pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable slivers (the "dead space" penalty)
    // Slivers between 1 and 7 are usually impossible to fill with typical item distributions
    let sliver_penalty = if post_residual > 0 && post_residual < 8 {
        20.0 * (1.0 - (post / 8.0))
    } else {
        0.0
    };

    // Reward bins that bring the residual closer to the mean of existing bins
    // This helps pack bins to similar levels, reducing variance in remaining space
    let variance_penalty = (post - mean_residual).abs() * 0.5;

    // Lookahead: if the next item is large, favor bins that leave enough space for it
    // If the next item is small, we are less concerned about leaving a large post_residual
    let next_item = next_item_size as f64;
    let lookahead_alignment = if next_item > 0.0 {
        if post >= next_item {
            -15.0 * (next_item / 100.0) // Reward fitting the next item comfortably
        } else {
            10.0 * (next_item / 100.0)  // Penalize stranding the next item
        }
    } else {
        0.0
    };

    // Dynamic thresholding: as we reach the end of the stream, prioritize closing bins
    // (reducing open_bins_count) over perfect packing efficiency
    let completion_pressure = (progress * 50.0) * (open_bins_count as f64).sqrt();

    // New bin candidate logic:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // We penalize opening a new bin heavily unless the fitting_bins_count is low
    // or the existing bins are too tight to accommodate future items.
    let new_bin_cost = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Necessary to open
        } else {
            35.0 + (progress * 20.0) // Cost to open new bin prematurely
        }
    } else {
        0.0
    };

    post + sliver_penalty + variance_penalty + lookahead_alignment + completion_pressure + new_bin_cost
}

