pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Penalty for creating a bin that is too empty (near 100) or too tight (near 0)
    // We use a quadratic form to favor residuals that allow for future item sizes.
    // The "ideal" residual is tuned by the current mean_residual to keep bins balanced.
    let target_residual = mean_residual * (1.0 - progress);
    let residual_penalty = (r - target_residual).powi(2);

    // Lookahead: penalize if the next item will not fit in the current post_residual
    let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), add a significant bias cost
    // to discourage opening new bins unless the current fitting bins are very poor.
    let new_bin_bias = if bin_residual == bin_capacity {
        (capacity * 0.4) + (progress * capacity * 0.2)
    } else {
        0.0
    };

    // Interaction term: penalize opening a new bin if we have many fitting options
    let fit_pressure = if bin_residual == bin_capacity {
        fitting_bins_count as f64 * 5.0
    } else {
        0.0
    };

    // Combine terms: Minimize score
    // Residual penalty ensures we fill bins efficiently.
    // Lookahead penalty accounts for the next item in the sequence.
    // New bin bias forces the algorithm to exhaust current bins before starting new ones.
    r + residual_penalty + lookahead_penalty + new_bin_bias + fit_pressure
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
