        }
    }

    // If it's a new bin, apply a dynamic threshold based on progress and open_bins_count.
    // We want to avoid opening a new bin if an existing one is a "good enough" fit.
    if is_new_bin {
        let open_penalty = (open_bins_count as f64).powf(1.5) * (1.0 - progress);
        score += 2500.0 + open_penalty;
    } else {
        // For existing bins, penalize residuals that are too small to be useful (fragmentation).
        // A residual of 1-9 is often "dead space".
        if post_residual > 0 && post_residual < 10 {
            score += 200.0 * (1.0 - progress);
        }
    }

    // Penalize creating bins that deviate significantly from the mean_residual of existing bins
    // to keep the packing density consistent across all active bins.
    let residual_diff = (post as f64 - mean_residual).abs();
    score += residual_diff * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #726: Harmonic Residual Optimization
    // Targets Best-Fit-Decreasing approximation by penalizing small remaining gaps (fragmentation)
    // and favoring bins that can accommodate the lookahead item (next_item_size).

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: If post_residual is small (1-9), it's likely "dead space".
    // We heavily penalize post_residuals that are too small to fit the smallest possible items.
    if post_residual > 0 && post_residual < 10 {
