    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 4. Scarcity Logic: If this is the only bin that fits the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && post_residual < 100 {
        score -= 100.0;
    }

    // 5. New Bin Thresholding: If we are considering a new bin (bin_residual == bin_capacity),
