            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            // No options, forcing a new bin is neutral.
            score -= 10.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

