        // Penalty for opening a new bin increases as we progress through the stream.
        score += 40.0 + (progress * 60.0) + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean Residual Alignment: Penalize bins that deviate significantly from 
    // the average usage, promoting uniform bin utilization.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation exponentially as the stream progresses
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress).powf(0.5) * 45.0 + 10.0
    } else {
        0.0
    };

    // Calculate "tightness" score: target smaller post_residuals (Best Fit)
    // but scale by the likelihood of future items fitting into the remaining space.
    // If post_residual is small, it's a good fit. 
    // If post_residual is large, we check if the next item could have fit better elsewhere.
    let mut score = post_residual as f64;

    // Favor bins that leave just enough room for the next item (Lookahead optimization)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        } else if post_residual < 10 {
            // Reward near-perfect packing (Very small residual)
            score -= 25.0;
        }
    }

    // Penalize creating "dead zones" (residuals too small for any item, 1-9)
    // unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    // Discourage opening new bins if there are plenty of fitting bins available
    if is_new_bin && fitting_bins_count > 0 {
        score += 30.0 / (fitting_bins_count as f64 + 1.0);
    }

    // Integrate mean_residual to encourage balancing
    // If this bin is much emptier than the average, prioritize filling it
    if !is_new_bin && (bin_residual as f64) > mean_residual {
        score -= 10.0 * progress;
    }

    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

