    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Harmonic Alignment: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // This creates "slots" for future items.
    if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 3. Lookahead Logic: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 4. Fitting Pressure: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. Global Efficiency: If the bin is a new bin, penalize it based on how many bins are already open.
    // This discourages opening new bins when the current load is already high.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // Dynamic thresholding: Near the end of the stream, be more aggressive with new bins
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 20.0;
    }

    // 6. Mean Residual Balancing: Penalize bins that deviate significantly from the mean state
    // to keep the "fill level" consistent across all open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

