    if bin_residual == bin_capacity {
        score += progress * 200.0;
    }

    // Fitting bins constraint:
    // If this is the only bin that can fit the item, prioritize it heavily 
    // to prevent unnecessary bin creation, weighted by how empty the bin is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0 / (1.0 + post);
    }

    // Global state coupling:
    // Penalize increasing the number of bins if the average residual is already high,
    // as it indicates we are spreading items too thin across many containers.
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * (mean_residual / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing
    // We prioritize bins that leave very little space (Best Fit)
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward placements that leave remainders 
    // that are multiples of common item sizes or "friendly" fractions of capacity.
    // We heavily penalize post_residuals that are "orphaned" (too small to fit common items).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Integration: If next_item_size exists, prioritize bins that 
    // can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0; // Reward bins that can fit the next item
        } else {
            score += 15.0; // Penalize bins that will force a new bin for the next item
        }
    }

    // 4. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fit quality is poor across all open bins
        // or if we have very few open bins.
        if fitting_bins_count > 0 {
            score += 60.0; // Strong penalty for opening a new bin unnecessarily
        }
    }

    // 5. Global Efficiency:
    // As the stream progresses, prioritize closing bins (lower mean_residual)
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64);

    // 6. Harmonic Modulo:
    // Penalize remainders that are prime or awkward, reward those that match 1/2, 1/3, 1/4 of capacity
    let harmonic_mod = (post_residual % 25) as f64;
    score += harmonic_mod;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
