    let progress = step_index as f64 / total_items as f64;
    if fitting_bins_count > 0 && bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // New Bin Logic: If we are considering a new bin (residual == capacity),
    // only choose it if the average residual of existing bins is already very low.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
