    } else {
        // Encourage using bins that are already partially filled to pack tighter
        // over the course of the stream
        score -= (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Penalize high fragmentation globally
    score += (mean_residual * 0.2) * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual_ratio = post / bin_capacity as f64;

    // Penalize creating tiny gaps (fragmentation) that are harder to fill later.
    // The "sweet spot" is either 0 (perfect fit) or large enough to accommodate future items.
    let fragmentation_penalty = if post > 0.0 && post < 20.0 {
        (20.0 - post).powi(2) * 2.5
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor leaving space for it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Dynamic threshold: As the stream progresses, become more aggressive in packing 
    // to avoid opening new bins late in the game.
    let progress_weight = 1.0 + (progress * 5.0);

    // Evaluate the cost of opening a new bin vs filling existing.
    // If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    let base_score = if bin_residual == bin_capacity {
        // New bin cost: increase as we near the end of the stream
        15.0 + (progress * 40.0) + (open_bins_count as f64 * 0.5)
    } else {
