    };

    // Coupling: If fitting_bins_count is low, we are constrained; lower the score 
    // to prioritize existing bins over opening new ones.
    let constraint_factor = if fitting_bins_count <= 1 { -5.0 } else { 0.0 };

    (base_score * progress_weight) + constraint_factor
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
