    // but we penalize bins that leave tiny, unusable fragments (e.g., 1-9) that block future items.
    // We use a non-linear quadratic penalty for "near-empty" residuals to discourage bad fragmentation.
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
