    // If we are late in the stream, favor filling existing bins aggressively.
    score += (open_bins_count as f64) * progress * 5.0;

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // We make it harder to open a new bin as we reach the end of the stream
    if bin_residual == bin_capacity {
