    }

    // Interaction with mean_residual: avoid bins that deviate too much from the average,
    // as these likely represent inefficient packing clusters.
    let dev = (post - mean_residual).abs();
    score += dev * 0.5;

    // If this is the only bin that fits, give it a significant boost to avoid new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
