    // Harmonic class logic: Favor bins that are "tight" relative to the mean residual
    // This encourages leveling the load across open bins
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // Only open if the current placement options are exceptionally poor
    if bin_residual == bin_capacity {
