        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the current fits are extremely poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty proportional to current open bin count.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.5);
    } else {
        // If it's an existing bin, reward bins that are already tight to maintain high density.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Scarcity Logic: If this is the last bin that can fit the item, prioritize it to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Progression Scaling: As we near the end of the stream, prioritize closing bins (minimize residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a significant penalty to avoid opening new bins unless necessary.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 2. Lookahead optimization: prioritize bins where the post_residual is close to the next_item_size.
    // This minimizes fragmentation by creating "perfect" fits for future arrivals.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
    }

    // 3. Prefer bins that are already closer to the mean residual to keep bin states uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 4. If this is the only bin that fits, strongly prioritize it to avoid wasting a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Penalize bins that leave very small, unusable slivers (e.g., < 10 units are often "dead" space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 6. Dynamic Scaling: As we reach the end of the stream, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals to keep bins tight.
    // 2. Lookahead: If next_item_size fits in post_residual, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0 + (next_item_size as f64 * 0.5);
    }

    // 3. New Bin Penalty: If bin_residual == bin_capacity, we are considering a new bin.
    // We only want to open a new bin if the current open bins are "too full" to be useful
    // for future items, or if we are near the end of the stream.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have fitting options, unless the mean residual is tiny.
            score += 60.0 - (mean_residual * 0.8);
        }
        // Increase likelihood of new bins as we approach the end to avoid straggler items.
        score -= (progress * 20.0);
    } else {
        // 4. Fragment Avoidance: Penalize leaving "unusable" gaps (e.g., < 10 units)
        // unless it's a perfect fit.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // 5. Global State: If we have many open bins, prioritize filling the most crowded ones.
        // Penalty for using a bin that is significantly emptier than the average.
        if (bin_residual as f64) > mean_residual {
            score += (bin_residual as f64 - mean_residual) * 0.2;
        }
    }

    // 6. Final constraint: Ensure we don't open new bins unnecessarily when items are small.
    if fitting_bins_count == 0 && bin_residual != bin_capacity {
        score += 1000.0; // Impossible to fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement
    let mut score = post_res;

    // Penalty for creating "slivers" (small, hard-to-fill residuals)
    // We penalize post_residuals that are too small to fit the smallest expected items (approx 10-15)
    if post_res > 0.0 && post_res < 15.0 {
        score += (15.0 - post_res) * 2.5;
    }

    // Lookahead logic: if we know the next item, penalize placements that block it
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            // High penalty if this placement forces a new bin for the next item
            score += 40.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: as the stream progresses, favor packing tighter to minimize open bins
    // If we have many bins open, increase the cost of opening a new one
    if bin_residual == bin_capacity {
        // This is the "Open New Bin" candidate
        // Penalize opening a new bin heavily if other bins have space
        score += (open_bins_count as f64 * 10.0) * (1.0 + progress);

        // Reward opening a new bin only if fitting_bins_count is low, 
        // but normalize by progress to avoid early-stream fragmentation
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Favor bins that are already "fuller" (lower post_residual)
        // Coupling with mean_residual to avoid uneven distribution
        score += (post_res - mean_residual).powi(2) * 0.1;
    }

    // Final scaling: prioritize packing tightly in the late stages of the stream
    score * (1.0 + (progress * 0.5))
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'fragmented' space that is too small for common items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Best-Fit Decreasing logic: heavily favor bins that result in near-zero residual (tightest fit)
    // We treat the post_residual as the primary cost, but adjust based on lookahead
    if next_item_size > 0 {
        // If the current post_residual is too small for the next item, penalize it
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // If it can fit the next item, reward this bin slightly to encourage packing
            score -= 5.0;
        }
    }

    // Harmonic class logic: penalize residuals that are not multiples of common item sizes (e.g., 20, 25, 33)
    // to keep the bin profile 'clean' for future items.
    if post_residual % 20 != 0 && post_residual % 25 != 0 {
        score += 2.0;
    }

    // If this is the last fitting bin, we are forced to use it. 
    // If it's a poor fit, it might be better to open a new bin if the item is large.
    if fitting_bins_count == 1 && post_residual > 30 && item_size < 50 {
        score += 10.0;
    }

    // Discourage opening too many bins early in the stream
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // This is a new bin candidate
        score += 40.0 * (1.0 - progress);

        // If we have many open bins, penalize opening a new one even more
        score += open_bins_count as f64 * 2.0;
    }

    // Align with mean residual to prevent outlier bin states
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // (1..10 is a "dead zone" for many distributions).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins when current bins are sufficient.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
