    // 4. Tight Fit Reward: Prefer bins that are nearly full (Best Fit principle).
    // Subtracting based on how much we filled the bin to encourage consolidation.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, 
    // prioritize closing bins (reducing open_bins_count) over perfection.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

