    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. New Bin Penalty: The "new bin" call has bin_residual == bin_capacity.
    // We heavily penalize opening a new bin unless the existing fits are extremely suboptimal.
    if bin_residual == bin_capacity {
