            // Severe penalty for creating a gap too small for the immediate future item.
            score += 40.0;
        }

        // Harmonic alignment: Penalize residuals that are not multiples of common item sizes (e.g., 20, 25).
        // This encourages "clean" bin states.
        let alignment_penalty = (post_residual % 20) as f64 * 0.5;
        score += alignment_penalty;
    }

    // 2. New Bin Thresholding: If this is an empty bin, evaluate based on current mean_residual.
    // If the mean_residual of current bins is already low, opening a new bin is less attractive.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score = 55.0; 
        // If existing bins are very full (mean_residual low), increase the cost of opening a new one.
        score += (100.0 - mean_residual) * 0.5;
    } else {
        // 3. Fitting Urgency: If this is the only bin that fits the item, make it highly attractive.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 4. Progress Scaling: As the stream nears completion, become more aggressive in packing to avoid leaving empty space.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // If a gap is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    if bin_residual == bin_capacity {
        // Only open a new bin if the current number of bins is low, or if 
        // the item is very large and would leave a terrible residual in existing bins.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward filling existing bins to keep open_bins_count low
        score -= (open_bins_count as f64) * 0.5;
    }

    // 3. Lookahead Logic: If the next item is large, prioritize keeping space for it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize if the current placement makes the bin unable to fit the next item
            score += 15.0;
        } else if (post_residual - next_item_size) < 5 {
            // Reward "Perfect Fit" scenarios for the lookahead
            score -= 20.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // provide a slight incentive to take it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Global Efficiency: If the current bin is significantly worse than the mean, penalize
    if bin_residual != bin_capacity && post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // However, we apply a non-linear scaling to favor tighter packing.
    score = score * (1.0 + (post_residual as f64 / bin_capacity as f64));

    // 2. Lookahead matching: If the post_residual is close to the next_item_size,
    // we want to reward that specific bin to keep it as a "perfect match" candidate.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward bins that can accommodate the next item perfectly.
