    // 3. Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), add a significant penalty
    // unless there are no other options or the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0; // Base cost to open a new bin
        // Reduce the penalty if the current item is very large, making it hard to fit elsewhere
        score -= (item_size as f64 * 0.4);
    }

    // 4. Global state awareness:
    // If we have many open bins, penalize creating more.
    score += (open_bins_count as f64 * 0.1);

    // 5. Mean residual balancing:
    // Avoid creating bins that are significantly worse than the current average.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 6. Last chance logic:
    // If this is the only bin that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual (Best Fit), but penalize fragmentation if next_item_size is large.
    // We heavily penalize opening new bins unless the current bin state is extremely poor (high post_residual).

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

