    } else {
        // 2. Fragment Penalty: If post_residual is small but > 0, it might be "dead space"
        // We prefer post_residual to be 0 (perfect fit) or large enough to fit next_item_size
        if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
            score += 15.0; // Penalty for stranding an item that could have fit
        }

        // 3. Global state awareness: If the bin is becoming too sparse compared to others, penalize it
        if (bin_residual as f64) > mean_residual * 1.5 {
            score += 5.0;
        }

        // 4. Tighten fitting if we are nearing the end of the stream
        if progress > 0.8 && post_residual > 10 {
            score += 10.0 * (1.0 - progress);
        }
    }

    // 5. Reward bins that lead to a perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
