        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 2. Penalty for opening new bins: Only open a new bin if the fit is truly terrible.
    // If we are considering a fresh bin (bin_residual == bin_capacity), penalize it 
    // unless fitting_bins_count is 0 or the current state is highly fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing capacity.
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other bin can fit, this is a necessary evil.
            score += 5.0;
        }
    }

    // 3. Fragmentation control: If the post_residual is very small (< 10), 
    // it often creates "orphan" space that cannot fit common items. 
    // We penalize these "dead-ends" unless they are perfect fits (0).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 1.5;
    }

    // 4. Global state awareness: If we are late in the sequence, tighten the constraints.
    // Progress ratio (0.0 to 1.0)
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.2;
    }

    // 5. Mean residual alignment: Favor bins that stay near the global mean residual
    // to keep the bin distribution uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large remaining space (waste).
    // The base score (post_residual) already favors tight fits (smaller post_residual).

    // 2. Lookahead optimization: If the next item can fit in the post_residual, 
    // reward this bin to keep the item flow packed.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Prevent fragmentation: If fitting_bins_count is low, we are running out of options.
    // If we are currently looking at a new empty bin (bin_residual == bin_capacity),
    // penalize opening it unless we have no other good options.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one could fit the item
            score += 45.0 + (progress * 20.0);
