        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // 5. Dynamic horizon: As the stream nears the end, prioritize filling bins 
        // more aggressively to avoid trailing leftovers.
        score -= (progress * 15.0) * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // 6. Extreme fit bonus: If post_residual is exactly 0, it's a perfect fit.
    if post_residual == 0 {
