            score -= 10.0;
        }
    }

    // 4. Fitting Constraint: If this is the last chance to fit the item in an existing bin,
    // lower the score to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: Keep residuals aligned with the mean to maintain bin uniformity.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

