    }

    // 5. Global state normalization:
    // Penalize opening new bins (bin_residual == bin_capacity) as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 + (progress * 20.0);
    }

    // 6. Mean Residual Balancing:
    // Avoid bins that deviate significantly from the global mean residual to keep bin levels uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
