    if post_residual > 0 && post_residual < 10 {
        score += 150.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly in the 
    // current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= (100.0 - gap as f64) * 0.5;
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins if we have many already,
    // but favor opening a new bin if the current fit is "sub-optimal" (large residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost for opening a new bin is high to encourage packing into existing ones.
        score += 50.0 + (open_bins_count as f64 * 2.0);
    } else {
        // If we are forced to pick a bin that leaves a large, awkward gap (e.g., 10-30),
        // we penalize it to encourage using bins that lead to tighter packing.
        if post_residual > 10 && post_residual < 35 {
            score += (35.0 - post_residual as f64) * 0.8;
        }
    }

    // 4. Scarcity Reward: If this is the last bin that can fit the item, 
    // reward it to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Progression Normalization: As we approach the end of the stream, 
    // become more aggressive about filling bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

