    // Penalty for creating a bin that is too empty early on.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin:
        // We only open a new bin if the score is lower than existing bins.
        // We scale this penalty by the current progress to encourage consolidation later.
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 + (progress * 20.0);
    } else {
        // 2. Lookahead Matching (Aggressive):
        // If the post_residual is close to the next_item_size, we reward this bin.
        // This is a "Perfect Fit" incentive.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score -= (100.0 - diff) * 0.25;

            // If post_residual is exactly enough for next_item, massive reward.
            if post_residual == next_item_size {
                score -= 50.0;
            }
        }

        // 3. Fragmentation Control:
        // Penalize bins that deviate significantly from the global mean residual.
        // We want to keep residuals uniform to increase future packing options.
        let residual_variance = (post_residual as f64 - mean_residual).abs();
        score += residual_variance * 0.15;

        // 4. Scarcity/Urgency:
        // If this is the last bin that can fit the item, we are forced to use it.
        // Give a slight preference to using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

