    let mut score = post_residual as f64;

    // Penalty for opening a new bin unnecessarily
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have fitting options
            score += 150.0 + (1.0 - progress) * 50.0;
        } else {
            // Reward opening a new bin if it's the only way to proceed
            score -= 20.0;
        }
    } else {
        // Lookahead: If next_item_size is large, avoid leaving a tiny gap that is unusable
        if next_item_size > 0 {
            let gap_after_next = post_residual as i32 - next_item_size as i32;
            if gap_after_next >= 0 && gap_after_next < 10 {
