                score += 40.0;
            } else if gap_after_next >= 0 {
                // Reward placements that create a "perfect" fit for the lookahead item
                score -= 15.0 * (1.0 - (gap_after_next as f64 / 100.0));
            }
        }

        // Global state: If we have many open bins, penalize creating more residual space
        // to encourage consolidating into fewer bins
        score += (open_bins_count as f64 * 0.5);

        // Dynamic adjustment: As we approach the end of the stream, prioritize 
        // tighter fits to minimize trailing bins
        if post_residual < 10 {
            score -= 10.0 * (1.0 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating bins with tiny, unusable residuals ("slivers") that are hard to fill later.
    // A post-residual of 1-5 is often worse than 0 (perfect fit) or >10 (usable space).
    let sliver_penalty = if post_residual > 0 && post_residual <= 5 {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Reward tighter packing (smaller post_residual) but modulate by lookahead.
    // If next_item_size is large, we prefer a larger post_residual to accommodate it.
    let lookahead_mod = if next_item_size > 0 {
        let needed = next_item_size as f64;
        if post_res < needed {
            (needed - post_res) * 2.0
        } else {
            0.0
        }
    } else {
        0.0
    };

    // If this is the only bin that fits, we are forced to take it (low score).
    // Otherwise, penalize opening new bins heavily as progress increases.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if fitting_bins_count == 0 {
            -100.0 // Must open new
        } else {
            (30.0 + (progress * 50.0)) * (open_bins_count as f64).sqrt()
        }
    } else {
        0.0
    };

    // Integrate the mean residual to keep bin states uniform.
    let balance_factor = (post_res - mean_residual).abs() * 0.1;

    post_res + sliver_penalty + lookahead_mod + new_bin_penalty + balance_factor
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
