    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin fits.
    // We only want to open a new bin if the current fit quality is very poor (high post_residual).
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we are at the end of the stream, discourage new bins.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 6. Crowding Penalty:
    // Discourage filling bins if we have many open bins already (try to consolidate).
    score += (open_bins_count as f64) * 0.5;

    // 7. Last Chance Logic:
    // If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
