    // 5. Global Mean Alignment: Encourage filling bins that are already closer to the mean 
    // capacity usage to maintain uniform bin states.
    let current_usage = (bin_capacity - bin_residual) as f64;
    score += (current_usage - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
