}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We want to minimize the post_residual to pack tightly.
    let mut score = post;

    // Penalty for leaving "unusable" space (gaps < 10 are often problematic)
    // We apply a non-linear penalty for small gaps that are too small for future items.
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - post / 10.0);
    }

    // Dynamic Lookahead Integration:
    // If the next item is large and won't fit in this post_residual, 
    // we penalize this bin to encourage saving space for the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Efficiency Coupling:
    // As the stream progresses, we become more aggressive in filling bins 
    // to avoid leaving too many bins partially full. 
    // We reward placements that align with the current mean_residual.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * progress;

    // New Bin Handling:
    // If this is a new bin (bin_residual == bin_capacity), we add a base cost 
    // that scales inversely with open_bins_count to prevent excessive bin creation.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 0.5);
    }

    // Fitting Constraint:
    // If this is the only bin that can fit the item, strongly prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic classes logic: prioritize bins that leave a post_residual 
    // which is highly compatible with the next_item_size or common item sizes.
    // We penalize 'dead space' (post_residual < 10) unless it's a perfect fit.

    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (small unusable residuals)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
    }

    // 2. Harmonic Alignment: Reward residuals that are multiples of common item sizes
    // or specifically match the next_item_size (lookahead optimization).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if the next item fits perfectly or leaves little waste
            score -= (bin_capacity - post_residual) as f64 * 0.2;
            score -= (next_item_size as f64 / (post_residual as f64 + 1.0)) * 10.0;
        } else {
            // Penalty if we cannot fit the next item anymore
            score += 15.0;
        }
    }

    // 3. New Bin Thresholding: 
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // We only open a new bin if the current mean_residual is very low (high fragmentation).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Higher penalty for opening new bins if we have many bins with decent space
            score += (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 4. Best Fit Decreasing logic: Favor bins that are already tight
        score += (bin_capacity - bin_residual) as f64 * 0.1;

        // 5. If this is the last chance to fit the item in existing bins, prioritize it
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 6. Global progression: As the stream ends, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
