    // 1. Dead Space Penalty: Penalize post_residual values that are too small to fit typical items (< 10)
    // but large enough to be wasteful. If post_residual is in [1, 9], it's high-risk.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: If this is the only bin that fits, reward it to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 4. New Bin Constraint: Heavily penalize opening a new bin unless the current mean_residual 
    // suggests the existing bins are already too crowded.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 20.0;
        } else {
            score += 60.0;
        }
    }

    // 5. Global Efficiency: Progressively favor tighter packing as the stream nears completion
    // to minimize the impact of remaining open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments
    // that are too small to fit any common item (typically < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Matching: If next_item_size is known, reward bins that leave
    // space exactly equal to or slightly larger than the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fits for the next item
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
        } else {
            // Penalize if the current placement makes the next item impossible to fit
            score += 40.0;
        }
    }

    // 3. Global Density Optimization: Balance load across bins
    // If post_residual is significantly lower than the mean, we are creating a tight bin.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 4. New Bin Thresholding: Prevent opening a new bin unless the current fit is terrible.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy base penalty.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Reduce new bin penalty if we have many open bins that are all nearly full
        if open_bins_count > 5 && mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // 5. Urgency: As we approach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
