        } else {
            // Otherwise, keep the cost of new bins moderate to allow for better packing
            score += 35.0;
        }
    } else {
        // 5. Dynamic thresholding: as we near the end of the stream, prioritize tight fits
        // to minimize the number of bins left open.
        if progress > 0.85 {
            score += (post_residual as f64) * 0.5;
        }
    }

    // 6. Penalty for creating "dead zones" (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
