    // We add a penalty for opening new bins (bin_residual == bin_capacity) that scales with progress
    if bin_residual == bin_capacity {
        score += 250.0 * (1.0 - (progress * 0.5));
    }

    // Interaction term: penalize bins that deviate significantly from the mean_residual
    // This encourages a uniform fill rate across all active bins
    score += (post_res - mean_residual).abs().powf(1.2);

    // If this is the only bin that fits the current item, prioritize it to avoid creating a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    score
}

