    } else {
        // Penalty for opening a new bin: proportional to how much space is left in current open bins.
        // If average residual is high, we shouldn't open a new bin.
        score += mean_residual * 0.5;
    }

    // 4. Tightness bias: Prefer bins that are already "fuller" (lower residual before placement).
