pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize fragmentation: higher post_residual (wasted space) is bad, 
    // but we weight it against the probability of fitting the next item.
    // If post_residual < next_item_size, it's a "bad" fit for the lookahead.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Favor bins that align with the global mean residual to keep packing density uniform.
    let density_balance = (post_res - mean_residual).abs() * 0.5;

    // Discourage opening new bins early in the stream unless the fit is excellent.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // As stream progresses, the penalty for opening a new bin decreases (end-game flexibility).
        (1.0 - progress) * 40.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Prefer bins where the remaining space is small (Best Fit logic),
    // but apply a non-linear scaling to favor tighter fits as the stream reaches the end.
    let base_score = post_res * (1.0 + progress * 0.5);

