    // 2. Lookahead matching: reward bins where the post_residual can fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for "perfect" alignment where residual is minimized after next step
            score -= (20.0 + (post_residual - next_item_size) as f64 * 0.5);
        } else {
