    // If the post_residual is in the range [1, 9], it is essentially "dead space" as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on open_bins_count
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead Optimization: If next_item_size is known, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin is a great candidate for the next item, reward it
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // This bin will be "stuck" for the next item, penalize slightly
            score += 5.0;
        }
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that fits the item, make it extremely attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Global Efficiency: As we reach the end of the stream, favor tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // However, we apply a non-linear scaling to protect "perfect" fits (residual 0).
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // significantly reward this bin to encourage "bin-pairing".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
