    // 3. Fragmentation Control: Penalize bins that deviate significantly from the 
    // global mean_residual, as they likely disrupt future packing density.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. New Bin Thresholding: If this is an empty bin (new bin candidate),
