        }
    } else {
        // 4. Existing Bin Preference: Encourage filling bins that are already partially full.
        // We calculate how much of the bin is used to prefer tighter packing.
        let usage = (bin_capacity - bin_residual) as f64;
        score -= usage * 0.2;
    }

    // 5. Dynamic Horizon: As the stream nears the end, become more aggressive 
    // about filling existing bins to avoid leftover capacity.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.3;
    }

    score
