    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress * 0.5);
    }

    // Interaction with existing state:
    // If we have many open bins, penalize opening another one significantly.
    // If we have few, be more lenient.
    score += (open_bins_count as f64) * 2.5;

    // If this is the only bin that fits, prioritize it strongly to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
