    // 2. Penalty for creating "orphan" space (between 1 and 9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead logic: If next_item_size fits in the post_residual, reward this bin heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Harmonic class management:
    // Prefer packing items into bins that are already partially filled to a high density.
    // If the bin is new (bin_residual == bin_capacity), penalize opening it if other bins are available.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 35.0;
    }

    // 5. If this is the only bin that can fit the item, favor it regardless of post_residual
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // 6. Distributional smoothing:
    // If we are nearing the end of the stream, prioritize minimizing open_bins_count
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 0.5;
    }

    // 7. Modulo-based "Tightness" bias:
    // Penalize post_residual values that are likely to be unusable (e.g., 1-9)
    // using the harmonic property of the capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
