        // If it's the only option, accept it, but with a base cost.
        score += 10.0;
    } else {
        // If this bin is the last chance for this item, reward choosing it 
        // to avoid fragmentation across many bins.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Penalize bins that are becoming too empty relative to the mean.
        if post_residual > (mean_residual as u32) {
            score += 5.0;
        }
    }

    // Dynamic horizon: As the stream nears the end, prioritize closing bins
    // by packing them as tightly as possible (favoring smaller residuals).
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) as they are hard to fill.
    // We heavily penalize post_residual < 10 unless it is 0 (perfect fit).
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        15.0 / (post + 1.0)
    } else {
        0.0
    };

    // Reward perfect fits (post_residual == 0)
    let perfect_fit_bonus = if post_residual == 0 { -20.0 } else { 0.0 };

    // Lookahead logic: if we know the next item, prioritize keeping space for it.
    // If post_residual is smaller than the next item, that bin becomes 'dead' for that item.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        10.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Favor bins that are already "tight" to keep the average bin usage balanced.
    // If bin_residual == bin_capacity (New Bin), apply a progressive cost based on open_bins_count.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_cost = if is_new_bin {
        (open_bins_count as f64 * 2.0) + (progress * 10.0)
    } else {
        0.0
    };

    // Non-linear coupling: Reward packing items into bins that are already partially filled 
    // to keep the number of open bins low, weighted by the stream progress.
    let density_score = (1.0 - (residual / bin_capacity as f64)) * 5.0;

    let mut score = post + fragmentation_penalty + perfect_fit_bonus + lookahead_penalty + new_bin_cost - density_score;

    // If this is the last chance for the current item (fitting_bins_count == 1) 
    // and it's not a perfect fit, prioritize this bin to avoid opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave small, unusable slivers.
    // If post_residual is < 10, it's likely dead space.
    if post_residual < 10 && post_residual > 0 {
