    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but reduce it if we are 
        // running out of efficient packing space (mean_residual is low).
        score += 40.0 - (mean_residual * 0.2);
    } else {
        // If we are forced to pick a bin, prioritize those that keep the bin 
        // occupancy balanced relative to the average.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Urgency: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
