    // If we are considering a new bin (bin_residual == bin_capacity), apply a heavy penalty.
    // This penalty scales with the progression of the stream to favor closing bins early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 + (progress * 20.0);

        // If there are many open bins, penalize opening another one unless necessary
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Mean residual equilibrium:
    // Avoid creating bins that deviate significantly from the mean residual of existing bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // If post_residual is in the range [1, 9], it is often "poisoned" space.
    if post_residual > 0 && post_residual < 10 {
