    // Penalty for creating a "sliver" (fragmented space that is hard to fill).
    // Slivers between 1 and 9 are extremely undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Adaptive pressure: If we have many open bins, penalize opening a new one 
    // or using a bin that results in a high residual compared to the mean.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Progress scaling: As we approach the end of the stream, prioritize tight packing 
    // over maintaining bin diversity.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

