    if next_item_size > 0 {
        let potential_next_residual = post_residual as i32 - next_item_size as i32;
        if potential_next_residual >= 0 {
            // Reward bins that can accommodate the next item perfectly
            score -= (100.0 - potential_next_residual as f64) * 0.5;
        } else if post_residual < next_item_size {
