    // Dynamic thresholding for new bins:
    // As the stream progresses, become increasingly conservative about opening new bins.
    if is_new_bin {
        // Base cost for opening a new bin is high. 
        // We scale this cost by progress to force packing into existing bins late in the stream.
        score += 40.0 + (progress * 60.0);

        // If only one bin fits the item, opening a new one is almost always bad
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Encourage balanced filling of existing bins by penalizing bins with high residuals
        // compared to the mean, preventing "fragmentation" across many bins.
        score += (bin_residual as f64 - mean_residual).powi(2) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

