        if fitting_bins_count > 0 {
            score += 200.0;
        } else {
            // If no other bins fit, prioritize opening the new bin with a baseline score.
            score = 50.0;
        }
    }

    // 2. Harmonic Lookahead: Favor residuals that are multiples of the next item size.
    // This reduces fragmentation by aligning bin space with future demand.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        // Reward placements where the post_residual is a perfect multiple of the next item.
        score -= (remainder == 0) as i32 as f64 * 15.0;

        // Penalize residuals that are slightly too small for the next item, 
        // as this creates "dead zones" that cannot be filled.
        if post_residual < next_item_size && post_residual > 0 {
            score += 40.0;
        }
    }

    // 3. Density Balancing: Avoid creating bins with high residuals if we are near the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Toward the end, be more aggressive about filling gaps.
        score += (post_residual as f64) * 0.5;
    }

    // 4. Mean Residual Coupling: Penalize bins that deviate significantly from the average fullness.
    // This encourages a balanced "global" fill rate, preventing isolated bins with tiny residuals.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
