    // 1. Penalty for leaving "dead space" (too small for any likely future item).
    // If post_residual is < 10, it is likely unusable given the 10-100 range.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item fits perfectly in the remaining space, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (50.0 - diff); // Strong reward for perfect or near-perfect fit for next item
    }

    // 3. Pressure to consolidate: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 4. Global balance: If this bin's residual is significantly better than the current mean, 
    // favor it to keep the mean residual low (Best Fit principle).
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. New Bin management: Penalize opening a new bin unless the fit is extremely poor in all current bins.
    if bin_residual == bin_capacity {
        score += 45.0; // Baseline penalty for starting a new bin
        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
