pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation exponentially as we approach the end of the stream
    let new_bin_penalty = if is_new_bin {
        (100.0 * (1.0 + progress.powf(2.0))) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Calculate "tightness" score: post_residual should be minimized.
    // We apply a non-linear penalty for larger residuals to favor Best Fit.
    let base_score = post_residual as f64 + (post_residual as f64).powf(1.5) * 0.1;

    // Lookahead logic: If the next item is large, prioritize keeping the residual 
    // large enough to fit it, or small enough that we don't waste space.
    let lookahead_penalty = if next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty if we create a bin that can't fit the next item 
            // when we could have potentially fit it elsewhere.
            (next_item_size - post_residual) as f64 * 1.5
        } else {
            // Reward keeping space for the next item
            -(post_residual - next_item_size) as f64 * 0.2
        }
    } else {
        0.0
    };

    // Global pressure: If few bins fit the item, we are forced to be less picky.
    let scarcity_adjustment = if fitting_bins_count <= 1 && !is_new_bin {
        -50.0 // Strong incentive to use the only available fitting bin
    } else {
        0.0
    };

    base_score + new_bin_penalty + lookahead_penalty + scarcity_adjustment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave small, unusable gaps.
    // Gaps < 10 are often "dead space" since min item size is 1.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Harmonic Lookahead: If the next item exists, favor leaving room for it.
    // If post_residual is just slightly too small for next_item_size, it's a "fragmentation trap".
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward finding a bin that fits the next item perfectly
        } else if post_residual < next_item_size && post_residual + 10 >= next_item_size {
            score += 40.0; // Heavy penalty for creating a bin that is almost useful but blocked
        }
    }

    // 3. Bin Conservation: Discourage opening new bins unless the fit is excellent.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 35.0; // Penalty for opening new bin if existing bins are available
        }
        score += 15.0; // Base cost for incrementing bin count
    }

    // 4. Mean Residual Balancing: Try to keep residual spaces consistent across bins.
    // If the current bin's post_residual is far from the mean, penalize (reduces variance).
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.2;

    // 5. Progression Weighting: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
