    // 5. New Bin logic: If this is an empty bin (bin_residual == bin_capacity), 
    // force a high cost unless we are forced to open one.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can fit the item.
            score += 60.0;
        } else {
            // If no bins fit, this is the only option, normalize score.
            score = 10.0;
        }
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize 
    // clearing out existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "fragmented" bin (residual too small to fit common items)
    // If post_residual is in the range (0, 10), it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item fits in this post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Global state awareness: if we have many bins open, try to pack tighter
    // If we have few bins open, be more lenient to avoid opening a new one
    let open_bins_factor = open_bins_count as f64 * 0.5;
    score += open_bins_factor;

    // Handling the "New Bin" candidate:
    // If bin_residual == bin_capacity, this is a new bin.
    // We only want to open a new bin if the existing fits are objectively terrible
    // or if the current progress suggests we are near the end.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin
        score += 35.0;

        // If we are near the end of the stream, penalize opening new bins more heavily
        score += progress * 20.0;

        // If there is only one fitting bin and it's a poor fit, compare it
        if fitting_bins_count > 0 && post_residual > 20 {
            score += 15.0;
        }
    } else {
        // If this is an existing bin, reward it if it's close to the mean residual
        // This encourages "leveling" the residuals across bins
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score -= residual_diff * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit logic).
    // We penalize small residuals (fragmentation) by applying a non-linear penalty
    // that grows as the stream progresses, forcing tighter packing later.
    let fragmentation_penalty = (1.0 / (post + 1.0)) * 50.0 * progress;

    // Lookahead logic: if the next item is large, favor bins that leave enough space
    // for it. If next_item_size is 0, we treat it as neutral.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), we add a substantial 
    // cost to discourage opening it unless no other bin is suitable.
    let open_bin_cost = if bin_residual == bin_capacity {
        // As the stream progresses, opening new bins becomes increasingly expensive
        // compared to trying to fit into existing, albeit imperfect, bins.
        15.0 + (progress * 40.0)
    } else {
        0.0
    };

    // Coupling: favor bins that bring the mean residual closer to the next_item_size
    // to keep the system balanced.
    let balance_score = (post - (mean_residual - item_size as f64)).abs() * 0.1;

    post + fragmentation_penalty + lookahead_penalty + open_bin_cost + balance_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

