    // If we are considering an empty bin (bin_residual == bin_capacity) but there are other options, 
    // impose a heavy penalty to force "Best-Fit" behavior unless the empty bin is the only logical choice.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Harmonic Modulo Bias: Favor residuals that are multiples of common item sizes (e.g., 20, 25)
    // to keep bins "clean" for upcoming items.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. Progression Scaling: As we near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    // 6. Mean Residual Alignment: Penalize bins that deviate significantly from the average occupancy.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
