    // reduce the penalty to prevent unnecessary new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: If current bin is emptier than the average, prefer it to 
    // balance the load across open bins.
    if (bin_residual as f64) > mean_residual {
