    // 4. Mean Residual Balancing: Keep open bins consistent
    // If this bin's post_residual is much larger than the current mean, penalize to keep it tighter.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
