        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item can fit in the remaining space, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when many are already active,
    // but allow opening new bins if the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // This is a candidate for a NEW bin.
        // We only prefer this if fitting_bins_count is low or if existing bins are too full.
        score += (open_bins_count as f64 * 2.0);
        if fitting_bins_count > 0 {
            score += 30.0; // Strong penalty for opening new bins if alternatives exist
        }
    } else {
        // Existing bin logic: Reward bins that keep the mean_residual stable.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 4. Tightness Calibration: Strongly prefer bins that end up nearly full (Best Fit principle).
    score += (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space": 
    // If the post_residual is small but > 0, it might be unusable for future large items.
    // We penalize based on how far the post_residual is from the next expected item size.
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty if we can't fit the next item here.
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward if the next item fits perfectly or leaves minimal slack.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. New bin penalty: 
    // If the bin is new (bin_residual == bin_capacity), we only want to open it if 
    // the current fitting options are extremely poor (e.g., leaving large gaps in all).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Forced to open a new bin.
            score = 10.0; 
        } else {
            // Penalize opening a new bin heavily unless it's the only option.
            score = 100.0 + (mean_residual * 2.0);
        }
    }

    // 4. Tightness objective: 
    // If this is the last fitting bin, favor it to avoid opening a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression adjustment: 
    // As we approach the end of the stream, prioritize closing bins (tightness).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

