    // If post_residual is very small (e.g., < 10), it's often better to leave a larger gap for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Coupling: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // 3. Global State Awareness: If we have many open bins, push toward consolidating (lower post_residual).
    // If we have very few bins, be more selective to avoid opening a new one later.
    let bin_pressure = (open_bins_count as f64) / (10.0 + progress * 50.0);
    score += bin_pressure * 15.0;

    // 4. New-Bin Thresholding: Discourage opening a new bin unless the current fit is catastrophic.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing fitting bins are all "poor" (high post_residual).
        // If fitting_bins_count is 0, we MUST open a new bin.
        if fitting_bins_count == 0 {
            score = -100.0;
        } else {
            // Otherwise, make the new bin score unattractive to force reuse.
            score = 60.0 + (mean_residual * 0.5);
        }
    } else {
        // Incentivize filling bins that are already partially full to keep global mean_residual low.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
