        score += 40.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If next_item_size fits in post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Further reward if it creates a "perfect" fit for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. Last Chance Logic: If this is the only bin that can fit the item, 
    // heavily prioritize it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. New Bin Threshold: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Penalize opening a new bin unless the existing bins are very full (mean_residual is low).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
