pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (the "fragmentation" penalty)
    // We heavily penalize post_residuals that are too small to fit common items (e.g., < 10)
    let fragmentation_penalty = if post_res > 0.0 && post_res < 10.0 {
        (10.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Reward bins that tightly fit the current item, adjusted by the lookahead.
    // If next_item_size fits in the post_residual, prioritize keeping the bin open.
    let lookahead_bonus = if next_item_size > 0 && post_res >= next_item_size as f64 {
        -20.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If this is the last chance to use an existing bin (fitting_bins_count == 1),
    // reduce the penalty for a poor fit to avoid opening a new bin unnecessarily.
    let scarcity_factor = if fitting_bins_count == 1 { 0.5 } else { 1.0 };

    // New bin logic: if bin_residual == bin_capacity, this is a "new bin" candidate.
    // We normalize the cost of opening a new bin by the current mean_residual.
    // If existing bins are very empty (high mean_residual), opening a new one is penalized.
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Combine factors:
    // post_res squared to favor "Best Fit" (smallest remaining space)
    // scarcity_factor modifies the impact of the residual to force fitting into existing bins.
    let score = (post_res * post_res * 0.01 * scarcity_factor) 
                + fragmentation_penalty 
                + lookahead_bonus 
                + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1221: Harmonic-Residual Balancing
    // We prioritize bins that result in "harmonic" residuals (multiples of common item factors)
    // and penalize the opening of new bins unless the current fit is highly suboptimal.

    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin (if fitting_bins_count > 0)
    // We heavily penalize starting a new bin if we have viable alternatives.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 2. Harmonic Class Logic: Reward residuals that are multiples of 10 or 20
    // These sizes are common in item distributions, leaving room for future items.
    let harmonic_penalty = if post_residual % 10 == 0 {
        -15.0
    } else if post_residual % 5 == 0 {
        -5.0
    } else {
        10.0
    };
    score += harmonic_penalty;

    // 3. Lookahead Synergy: If next_item_size fits in the post_residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Mean Residual Drift: Discourage creating bins that deviate significantly from the mean
    // This helps maintain a uniform "fill" across all active bins.
    let drift = (post_residual as f64 - mean_residual).abs();
    score += drift * 0.5;

    // 5. Critical Thresholding: If this is the last chance for the item (fitting_bins_count == 1)
    // and the post_residual is very small (< 5), it's a "perfect" fit.
    if fitting_bins_count == 1 && post_residual < 5 {
        score -= 50.0;
    }

    // 6. Progression factor: As the stream nears the end, be more aggressive with packing
    // to avoid leaving too many bins half-empty.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" creation:
    // If post_residual is small but positive (e.g., 1-9), it is often impossible to fit
    // subsequent items. We penalize this heavily to force tighter fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead optimization:
    // If we know the next item, penalize bins that cannot fit it after this placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that can accommodate the next item perfectly (Best Fit property)
            score -= (bin_capacity - post_residual) as f64 * 0.1;
        }
    }

    // 3. Open bin pressure:
    // Penalize opening a new bin if we have existing capacity.
    // If this is a new bin (bin_residual == bin_capacity), add a significant cost.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting constraints:
    // If this is the only bin that can fit the item, prioritize it (reduce score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global density balancing:
    // Favor bins that align with the current average residual to keep bin usage uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit principle
    // We start with the post_residual (the smaller, the better).

    // 2. Penalty for creating "dead space": 
    // If the post_residual is small but not zero, it's often a "bad" fit.
    // We penalize very small residuals (e.g., 1-9) unless they are 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. 2-Step Lookahead (The "Perfect Fit" Incentive):
    // If we can fit the next item perfectly into this new residual, reward it heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // If it fits exactly, minimize the score significantly.
        if diff == 0.0 {
            score -= 40.0;
        } else {
            // Otherwise, reward based on how well it accommodates the next item.
            score -= (20.0 / (diff + 1.0));
        }
    }

    // 4. Global State Awareness:
    // If we are running out of bins or the stream is nearing the end, 
    // prioritize packing tighter (lowering the score).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 5. Managing Open Bins:
    // If this is the only bin that fits the current item (fitting_bins_count == 1),
    // we should be careful not to create a "dead" bin.
    if fitting_bins_count == 1 && post_residual < 15 {
        score += 15.0;
    }

    // 6. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the current mean_residual is very high 
    // (meaning we have plenty of space elsewhere) or if we are forced to.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open the first bin
        } else {
            // Increase the cost of opening a new bin based on the mean_residual of existing ones.
            // If mean_residual is low, we are already tight; don't open a new bin.
            score += 45.0 + (mean_residual * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
