}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // We favor bins that leave the smallest residual after placement.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead optimization:
    // If we have a next item, penalize bins that cannot fit the next item after this one.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 45.0; // Penalty for stranding the next item
        } else {
            // Reward bins that can perfectly fit the next item (synergy)
            let synergy = (post_residual - next_item_size) as f64;
            score -= (100.0 - synergy) * 0.2;
        }
    }

    // 3. Global state pressure:
    // If fitting_bins_count is 1, it's our last chance to use an existing bin.
    // Discourage opening new bins unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // High barrier to opening a new bin
        }
        // As the process nears the end, become more aggressive about opening new bins
        score -= progress * 20.0;
    }

    // 4. Density Balancing:
    // Avoid creating "outlier" bins that deviate significantly from the mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Final adjustment: Prefer keeping the bin count low by slightly penalizing
    // the creation of more bins relative to total progress.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large residual (Best-Fit principle)
    let mut score = post_res;

    // Favor bins that become "tight" (post_residual near 0)
    // We add a penalty for "loose" bins, but modulate this by progress.
    // Near the end of the stream, we are more aggressive about closing bins.
    let tightness_penalty = (post_res * post_res) / (bin_capacity as f64 * (1.0 - 0.5 * progress));
    score += tightness_penalty;

    // Lookahead: If next_item_size is large, avoid leaving a residual that cannot fit it.
    // If post_residual < next_item_size, we penalize the bin for creating "dead space".
    if next_item_size > 0 && post_residual < next_item_size {
        let dead_space_penalty = (next_item_size - post_residual) as f64 * 1.5;
        score += dead_space_penalty;
    }

    // New Bin Logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the mean_residual of existing bins is already very small
    // (meaning they are nearly full) or if we are forced to.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost is high, but decreases as current bins fill up.
        // We use mean_residual to judge global fill state.
        let new_bin_cost = 45.0 + (mean_residual * 0.5);
        score = new_bin_cost;
    } else {
        // If it's the last chance (only one bin fits), prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Penalize bins that deviate significantly from the mean_residual to keep pack density uniform.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals < 10 are often hard to fill)
    // We heavily penalize post_residuals between 1 and 9 to favor tight packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Harmonic Class Logic: Favor residuals that are multiples of common item sizes
    // If the post_residual is a multiple of 20, it's likely to fit future items.
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 3. Lookahead Logic: If the next item can fit in the remaining space, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Thresholding: Avoid opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), penalize it significantly
    // unless there are no other viable options (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0;
        } else {
            score -= 10.0;
        }
    }

    // 5. Progression damping: As we near the end of the stream, prioritize closing bins
    // by penalizing empty space more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 0.5;

    // 6. Balance: Favor bins that are closer to the mean residual to keep bin levels uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while avoiding "unusable" small gaps (1..9).
    // Penalize opening new bins unless the fit is perfect or we have too many open bins.

    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (unusable gap < 10)
    // Small gaps are often dead space because items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Heuristic for new bin: 
    // Only choose a new bin if it's the only option or if it results in a perfect fit (0 residual).
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score = 0.0; // Perfect fit in new bin is ideal
        } else {
