        // 4. Global state adjustment:
        // Penalize filling bins that are already well-packed if there are many open bins,
        // to encourage using up the most "fragmented" bins first.
        score += (mean_residual - post_residual as f64).max(0.0) * 0.2;

        // 5. Criticality: If this is the only bin that fits the item, make it highly attractive.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // As post_residual approaches 0, the penalty grows exponentially (1/x behavior).
    // The exponent is modulated by the remaining space fraction.
    let fragmentation_penalty = 1.0 / (post + 0.1).powf(1.5);

    // Reward bins that align with the next item size (Lookahead synergy).
    // If post_residual is close to next_item_size, we effectively "match" the next piece.
    let next_match = if next_item_size > 0 {
        (post - next_item_size as f64).abs()
    } else {
        0.0
    };

    // Strategy: In early stages, favor Best-Fit (low post). 
    // In late stages, favor tighter packing to avoid opening new bins.
    let progress_weight = 1.0 + (progress * 5.0);

    // If this is the only bin that fits the item, make it highly attractive to prevent opening a new bin.
    let desperation_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -500.0
    } else {
        0.0
    };

    // If considering a new bin, penalize it based on how many bins are already open 
    // and how much "mean_residual" is wasted elsewhere.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 10.0) + (mean_residual * 0.5)
    } else {
        0.0
    };

    let base_score = post * progress_weight;
    let interaction = (fragmentation_penalty * 2.0) + (next_match * 0.8);

    base_score + interaction + desperation_bonus + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
