        score += (open_bins_count as f64) * 15.0;
        // If there are other bins that could fit the item, penalize opening a new one further.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tightness Reward: Favor bins that become very full (post_residual < 5).
    if post_residual < 5 {
        score -= 20.0;
    }

    // 5. Progression Scaling: As the stream nears the end, become more aggressive 
    // about closing bins (reducing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual (Best-Fit principle).
    // This is already the baseline 'score'.

    // 2. Penalty for opening a new bin unnecessarily:
    // If this is a new bin (bin_residual == bin_capacity) and other bins could fit the item,
    // apply a heavy penalty to discourage fragmentation.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 3. Lookahead optimization:
    // If the post_residual is close to the next_item_size, reward this bin to create a perfect match.
    // We reward if post_residual >= next_item_size, to ensure future feasibility.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (50.0 / (1.0 + diff)); 
        } else {
            // Penalize if the next item won't fit in this bin, forcing dispersion.
            score += 20.0;
        }
    }

    // 4. Global balance:
    // If the bin's post_residual is significantly worse than the current mean_residual,
    // penalize it to keep open bins packed similarly.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Urgency:
    // As the stream progresses, prioritize closing bins (lower residual) to reduce total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Minimize post_residual (Best-Fit principle).
    // Penalize large post_residuals exponentially to favor tight fits.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Awareness:
    // If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Fragmentation Control:
    // Avoid leaving small, unusable gaps (1-9) that are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // 4. Global State Balancing:
    // If we have many open bins, penalize opening a new one.
    if is_new_bin {
        score += (open_bins_count as f64) * 15.0;

        // If the current item fits in existing bins, discourage opening a new one
        // unless the existing bins are very full (low mean_residual).
        if fitting_bins_count > 0 {
            score += 60.0 * (1.0 - (mean_residual / bin_capacity as f64));
        }
    } else {
        // Favor bins that are already "half-full" to consolidate space.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // 5. Dynamic Time Horizon:
    // Towards the end of the stream, prioritize closing bins (Best-Fit becomes more aggressive).
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base heuristic: Minimize post_residual (Best Fit principle)
    // We treat post_residual as the primary cost.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As we progress through the stream, opening new bins becomes increasingly 
    // expensive to prevent fragmentation near the end of the sequence.
    if is_new_bin {
        score += 25.0 + (progress * 40.0);
    }

    // Lookahead coupling: 
    // If the next item exists, penalize bins that leave a post_residual 
    // just smaller than the next_item_size, as this forces a new bin later.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Global state coupling:
    // If we have many bins open, prioritize filling bins that are already 
    // "tight" (low mean_residual) to consolidate space.
    if !is_new_bin {
        let tightness_factor = (mean_residual - post_residual as f64).abs();
        score -= tightness_factor * 0.5;
    }

    // Criticality adjustment:
    // If this is the only bin that can fit the current item, prioritize it 
    // heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Non-linear curvature:
    // Penalize very small gaps (1-5) that are hard to fill later,
    // unless it is a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 6 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Harmonic/Residual coupling: Reward post_residuals that are perfect factors or high-density
    let density = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
