    }

    // 6. New bin penalty: If this is a new bin, penalize it relative to open bin count
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0) + (100.0 * (1.0 - (step_index as f64 / total_items as f64)));
    }

    // 7. Harmonic adjustment: Reward post_residuals that leave space for multiples of 25 (common capacity fraction)
    if post_residual % 25 == 0 {
