pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating bins that are nearly empty at the end of the stream
    let end_game_penalty = progress * (bin_capacity as f64 - post_res);

    // Favor fits that leave very little space (Best Fit)
    // We use a quadratic penalty for the post_residual to prioritize tighter packing
    let fit_score = post_res * post_res;

    // If we have a lookahead, favor bins that leave enough room for the next item
    let mut lookahead_bonus = 0.0;
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            lookahead_bonus = -50.0 * (1.0 - (post_res - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Penalize bins that block the next item if we are running out of bins
            lookahead_bonus = 25.0 * (1.0 - progress);
        }
    }

    // Discourage opening new bins unless necessary
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one could fit the item
            500.0 * (1.0 - progress * 0.5)
        } else {
            // Opening a new bin is mandatory if no existing bin fits
            -100.0
        }
    } else {
        0.0
    };

    // Combine factors
    // We want to minimize the score, so bonuses are negative.
    fit_score + end_game_penalty + lookahead_bonus + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
