    // Reduce penalty for using a new bin or a slightly suboptimal bin if we are constrained.
    let constraint_factor = (fitting_bins_count as f64).recip().sqrt();

    let mut score = waste_penalty + new_bin_penalty + (lookahead_penalty * constraint_factor);

    // If we have many open bins, penalize opening even more to favor consolidation.
    score += (open_bins_count as f64).powf(1.1) * 2.0 * is_new_bin;

