    }

    // 4. Global Density Balance: Avoid creating too many bins if the current average residual is already high.
    // If mean_residual is high, we should favor filling existing bins more aggressively.
    if mean_residual > 20.0 {
        score -= (bin_capacity - bin_residual) as f64 * 0.5;
