        // If we are forced to open a bin because no other bin fits, lower the cost
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // 4. Global State Awareness: Penalize creating many bins if we have a high mean_residual (high fragmentation)
    // If mean_residual is high, we want to consolidate into existing bins
    if open_bins_count > 0 {
        score += (mean_residual * 0.2);
    }

    // 5. Urgency: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    // We want to minimize the post_residual to pack tightly.
    let mut score = post;

    // Penalty for creating a bin that is too small for common future items.
    // If post_residual is small but not zero (e.g., 1-9), it creates "dead space".
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Lookahead logic: if next_item_size is large, favor bins that leave enough space for it.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0; // Strong reward for accommodating next item
        } else if post_residual < 20 {
            score += 10.0; // Penalty for stranding the next item
        }
    }

    // Dynamic thresholding based on stream progress.
    // Near the end of the stream, prioritize closing bins (lower open_bins_count).
    if progress > 0.85 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // If this is a new bin (bin_residual == bin_capacity):
    // Only open it if the average residual of existing bins is already very low,
    // or if the item absolutely cannot fit elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0; // Must open
        } else {
            // Heavily penalize opening a new bin if we have fitting options
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // Coupling: Reward bins that align with the global mean residual to keep bins uniform.
    let dev = (post - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
