    // Harmonic Class Logic: Reward placements that leave room for common item sizes
    // If the residual is a multiple of 20, it's highly versatile for mid-sized items
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 10.0;
    }

    // Threshold logic for new bins:
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it
    // unless the mean_residual is already very low (high fragmentation)
    if bin_residual == bin_capacity {
        score += 35.0;
        if open_bins_count > 0 && mean_residual < 20.0 {
