    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Mean residual balancing: Encourage placing items in bins that deviate 
    // from the mean residual to keep distribution uniform.
