    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // We aim for a Best-Fit approach that favors tightness, but penalizes 
    // leaving "sliver" residuals that are too small to be useful for the next item.
    // The cost function is non-linear to penalize extremely small residuals (dead space)
    // and extremely large residuals (wasted capacity).

    // Base score: punish larger post-residuals quadratically
    let mut score = post.powi(2) * 0.01;

    // Penalize "sliver" space: residuals between 1 and 9 are often useless
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item fits into this post_residual, reduce the score
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Stream progression adjustment:
    // Early in the stream, be more aggressive/greedy (favor tight fits).
    // Late in the stream, favor keeping bins open to consolidate remaining items.
    score += (progress * 10.0) * (open_bins_count as f64 / 10.0);

    // If this is a new bin (bin_residual == bin_capacity), set a threshold.
    // We only open a new bin if the best existing fit is objectively "bad" 
    // (e.g., leaves a very poor residual or forces an inefficient distribution).
    if bin_residual == bin_capacity {
        // High penalty for opening new bins; reduces as we get closer to the end.
        score += 45.0 * (1.0 - (progress * 0.5));
    } else {
        // If it's the last bin that fits, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Normalize against the mean residual to prevent massive variance
    score += (post - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
