    } else {
        0.0
    };

    // Combine terms:
    // 1. Post residual (standard Best Fit)
    // 2. Fragmentation (non-linear penalty)
    // 3. New bin overhead
    // 4. Lookahead anticipation
    post + fragmentation_penalty + new_bin_penalty + lookahead_penalty
}

