            // Excellent: we can fit the next item here, prioritize this bin
            score -= 40.0;
        } else {
            // Bad: we cannot fit the next item, penalize slightly based on how much space we waste
            score += 5.0;
        }
    }

    // 3. Prevent opening a new bin prematurely
    // If this is a new bin (residual == capacity), penalize it relative to the fitting_bins_count
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // We have existing bins that can fit, so opening a new one is expensive
            score += 60.0 + (fitting_bins_count as f64 * 10.0);
        } else {
            // No choice, we must open a new bin
            score -= 100.0;
        }
    }

    // 4. Global balance: Encourage filling bins that are already "fuller" than the average
    // This keeps the remaining space in open bins more uniform
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 10.0;
    }

    // 5. Finalize by rewarding configurations that approach perfect packing (residual 0)
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space (post_residual) 
    // to keep bins tightly packed.
    score += (post_residual as f64) * 0.5;

    // 2. Lookahead Integration: If the next item fits into the post_residual, 
    // strongly incentivize this bin to minimize future bin openings.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
