    // 3. Fragmentation Avoidance: Penalize residuals that are too small to be useful 
    // (e.g., < 10) unless they reach exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Global State Balancing: If we have many open bins, prioritize packing 
    // into existing bins (lower score) to consolidate.
    if open_bins_count > 0 {
