    // unless the current fit quality is extremely poor.
    if bin_residual == bin_capacity {
        // If there are other bins that could fit the item, penalize opening a new one.
        if fitting_bins_count > 1 {
            score += 45.0;
        } else {
            // If this is the only option or the item is large, make it neutral.
            score += 15.0;
        }
    }

    // 6. Progress Scaling: As we approach the end of the stream, 
    // become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
