    // We heavily penalize post_residuals that are smaller than the smallest likely future items.
    // If post_residual is < 10, it's likely wasted space.
    if post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead: If the next item is large, prioritize bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we increase the score (penalize).
    if next_item_size > 0 {
        if post < (next_item_size as f64) {
