        }
    }

    // Dynamic adaptation: As we reach the end of the stream, prioritize closing bins
    // by rewarding placements that result in very low post_residual (Best Fit).
    // Early in the stream, we are more tolerant of slightly larger post_residuals to keep
    // space open for future flexibility.
    let tightness_factor = 1.0 - progress;
    score += (post * tightness_factor * 0.5);

    // If this is the only bin that can fit the item, prioritize it highly to avoid 
    // the overhead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New Bin Logic: Only open a new bin if the current existing bins force a very poor fit.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already quite low,
        // suggesting they are "packed" and unlikely to fit future items well.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score += 5.0; 
        } else {
            // Otherwise, make opening a new bin expensive to encourage filling existing ones.
            score += 30.0 + (progress * 20.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
