        score += 85.0 * (1.0 - (open_bins_count as f64 / (total_items as f64).sqrt()));
    }

    // Coupling: If we are near the end of the stream, prioritize closing bins 
    // (low residual) to maximize capacity utilization.
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals that are "near-misses" for future large items
    // If post_residual is small but not zero, it creates "dead space" that cannot fit common items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Logic: If the next item is large, favor bins that can accommodate it.
    // If current post_residual is smaller than next_item_size, we penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 3. Harmonic Class Logic: Reward residuals that align with common item sizes (20, 25, 33, 50).
    // These fractions often allow for cleaner packing.
    let residual_mod = post_residual % 25;
    if residual_mod == 0 {
        score -= 10.0;
    }

    // 4. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it 
    // unless the current open bins are very full or the item is hard to fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin could fit it.
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no existing bin fits, it's a forced opening.
            score -= 5.0;
        }
    }

    // 5. Progression awareness: 
    // As the stream nears the end, become more aggressive in packing to avoid leaving partially filled bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    // 6. Balance penalty: 
    // Discourage creating bins that are significantly below the mean residual of other bins.
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

