    score += (post_residual as f64).powf(1.2) * (1.0 - 0.5 * progress);

    // 2. Lookahead Sensitivity: If the next item is large, avoid leaving tiny gaps 
    // that cannot accommodate it (i.e., avoid post_residual < next_item_size).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
