    // 3. Global State Balancing: If we have many bins open, we want to prioritize 
    // filling them (Best Fit) rather than opening new ones.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: higher when we have many open bins already.
        score += 15.0 + (open_bins_count as f64 * 0.8);
    } else {
