        // from the mean residual of existing bins to keep bin states uniform.
        score += ((post_residual as f64 - mean_residual).abs()) * 0.5;
    }

    // 4. Critical Threshold: If this is the last chance for this item, reduce penalty.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // 5. Final adjustment: If the item fits perfectly, reward heavily.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space remaining (Best Fit principle).
    // Penalize smaller residuals (tight fits) if they leave "orphaned" gaps that are too small for common items.
    // We target a post_residual that is either 0 (perfect) or large enough to accommodate the lookahead.
    let mut score = post_res;

    // Penalty for creating a "sliver" (a gap too small for most items, e.g., < 10).
    // We apply a non-linear penalty to residuals in the range (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead coupling: If the next item cannot fit in the current post_residual,
    // we penalize this bin to favor bins that leave enough space for the next item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 35.0 * (1.0 - progress);
    }

    // New bin logic: Only consider opening a new bin if the current fit is extremely poor
    // relative to the mean residual of existing bins, scaled by progress.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early in the stream, 
        // but become more lenient as the stream progresses.
        score = 40.0 + (30.0 * (1.0 - progress));
    } else {
        // Favor bins that align with the current mean residual to keep distribution uniform.
        let deviation = (post_res - mean_residual).abs();
        score += 0.5 * deviation;
    }

    // Heavily penalize forcing a new bin if other bins are available and capable.
    if fitting_bins_count > 0 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
