    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        (25.0 * (1.0 - progress)).powf(1.5) + (open_bins_count as f64 * 0.5)
    } else { 
        0.0 
    };

    // Best-Fit Decreasing intuition: Minimize post_residual, but heavily penalize 
    // leaving "dead zones" (small residuals that are unlikely to fit future items).
    // If post_residual is < 10, it is likely wasted space unless it fits the next item.
    let mut dead_zone_penalty = 0.0;
    if post < 10.0 && post > 0.0 {
