    }

    // 5. Density Balancing: 
    // If the bin is nearly full (post_residual < 10), it's a "dead" bin. Reward closing it off.
    if post_residual < 10 {
        score -= 20.0;
    }

    // 6. Progression Scaling:
    // As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize unusable small gaps (Dead Space Avoidance)
    // If post_residual is small but > 0, it's often a "poison" gap that can't fit most future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded
        score -= 20.0;
    }

    // 2. Open Bin Pressure
    // If we have many open bins, penalize opening a new one significantly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 15.0;
        // Discourage opening a new bin if we have plenty of space in existing ones
        score += mean_residual * 0.5;
    }

    // 3. Lookahead coupling
    // If we know the next item, prioritize keeping space that can fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin is "future-proofed" for the next item
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // This bin will likely be unable to fit the next item
            score += 5.0;
        }
    }

    // 4. Scarcity adjustment
    // If this is the last bin that can fit the item, prioritize it to avoid creating new bins unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 5. Progression scaling
    // As we approach the end of the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space to keep bins tight.
    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward the placement.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless no other bin can fit the item or the remaining space is extremely fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 65.0; // Strong penalty for opening a new bin unnecessarily
        }
    } else {
        // 4. Mean Residual Balancing:
        // If this bin's post_residual is significantly worse than the current mean, 
        // add a penalty to prevent "bloating" the average residual.
        if post_residual as f64 > mean_residual + 10.0 {
            score += 15.0;
        }

        // 5. Urgency factor: If this is the only bin that can fit the item, 
        // treat it as a high-priority candidate to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Progressive packing: As we near the end of the stream, 
    // be more aggressive about packing into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}
